insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 1, 'The EKPAN lottery is typed into the VOI Analyzer at full precision: Bright spot 46.000000 percent, success given Bright spot 64.673913 percent, success given No bright spot 9.722222 percent, against a stated success chance of 35 percent. What does the consistency check compute?', '["The sum of the two posteriors, which must reach 100 percent before the Analyzer will print any value of information for the survey.", "The indicator weighted average of the two posteriors, 0.297500 plus 0.052500, which is 0.350000 and leaves only binary residue as the delta.", "The likelihoods recovered from the posteriors, 0.850000 and 0.250000, each compared in turn against the stated success chance of 0.350000.", "The posterior after No bright spot read alone against the stated chance, because it is the more likely of the two readings on this survey."]'::jsonb, 1, 'Implied success is the sum over readings of each reading''s chance times its posterior; on the EKPAN lottery 0.460000 x 0.646739 + 0.540000 x 0.097222 returns 0.350000 with a delta of 5.551115e-17, so the entries are consistent and the gross voi reads 19.84.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 2, 'IRRI is the Analyzer''s default study with both Positive Seismic and Negative Seismic typed as 20 / 80 percent. What does the repaired Analyzer show?', '["A gross voi of -15.00 and a netVoi card of -25.00, because after either reading the best action is Do Not and the with side comes to 0.", "A refusal naming the sum in percent, since two indicators typed with identical outcome chances do not form a distribution at all.", "Every card at 0.00, since a withheld value is printed as zero so that the verdict sentence can still call the survey value neutral.", "EMV without information 15.00 and EVPI 63.00, with every other card and the diagram withheld."]'::jsonb, 3, 'The readings imply a 0.200000 success chance against a stated 0.300000, so consistent is false and withheld is true; the -15.00 and -25.00 are pre-repair cards and history, and the two surviving cards use only the stated outcome chances.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 3, 'Why does IRRI imply a success chance of 0.200000 whatever its indicator chances of 40 and 60 percent are typed as?', '["Both readings carry a success chance of 20 percent, and a weighted average of equal numbers returns that number for any weights.", "The engine substitutes the smallest outcome chance typed on the form whenever the entries disagree with the stated chances.", "The indicator chances enter only the value of information, and the check reads the posteriors of the first indicator listed, Positive Seismic.", "The indicator chances are rescaled until they reproduce a stated chance, and 20 percent is the closest those entries reach."]'::jsonb, 0, 'Implied success is 40 percent of 20 percent plus 60 percent of 20 percent, which is 0.200000; the delta against the stated 0.300000 is -0.100000, far past the 0.005 allowance.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 4, 'The published justInsideTolerance case states 0.300000 / 0.700000 and implies 0.305000 / 0.695000. What does the repaired engine report?', '["Consistent false, because 0.305 - 0.3 is 0.0050000000000000044 in binary, above 0.005, which is the result recorded as finding D1.", "Consistent false, because the allowance is relative, half a percent of the stated 0.300000, and a delta of 5.000000e-3 is far beyond it.", "Consistent true, because the boundary is inclusive and a 1e-12 allowance absorbs the binary residue in 0.305 - 0.3.", "Consistent true with a boundary mark beside the cards, showing the delta sits exactly on the half percent line."]'::jsonb, 2, 'Before the EC4-0 repair the engine had no allowance and called this case inconsistent; D1 is resolved, a delta of exactly 5.000000e-3 now reads consistent true, and nothing grades it as sitting on the line.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 5, 'On the Analyzer defaults the gross voi is 33.00 at an implied success chance of 0.300000 and 34.75 at 0.305000 (consistentAtHalfPercent), while the pre-repair 35.10 at 0.306000 is now withheld. What does the climb from 33.00 to 34.75 show?', '["The typed posteriors describe a sharper survey, and posteriors further from the prior always carry more information.", "Part of an accepted value can be extra success the stated chances never granted, so a pass does not certify the value.", "The allowance rescales the posteriors onto the stated chances before valuing, so 34.75 includes a correction the engine adds.", "It is binary residue from the 1e-12 allowance, so 33.00 and 34.75 describe the same survey to two decimals."]'::jsonb, 1, 'The value climbs with the contradiction inside the half point: 34.75 carries the same kind of error as the withheld 35.10, only less of it, and nudging entries under the line does not make them agree.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 6, 'On the EKPAN lottery, posteriors typed 65.000000 / 10.000000 and 65.000000 / 9.000000, both with Bright spot at 46.000000 percent, print the same gross voi of 20.51. Why?', '["After No bright spot the Analyzer''s best action is Do Not at either posterior, and Do Not pays 0 at any success chance.", "The Analyzer rounds each typed posterior to the nearest 5 percent before valuing, so 9 and 10 percent become one entry.", "Both rows pass the half percent check, and every accepted row prints the value the full precision entries would have given.", "A posterior below 10 percent is treated as a dry reading and valued as if the success chance after it were exactly zero."]'::jsonb, 0, 'The posterior after No bright spot multiplies a branch worth nothing, so the card cannot see it; on the EKPAN lottery full precision prints 19.84, so 20.51 overvalues the survey by rounding alone.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 7, 'The EKPAN lottery typed with posteriors rounded to 64.700000 and 9.700000 gives an implied success chance of 0.350000 and a delta of 0.000000e+0. What does that result certify?', '["That the entries match the survey, so 19.89 is the survey''s value and the 19.84 printed at full precision is the approximation.", "That the posteriors were derived by Bayes, since only posteriors derived from likelihoods can land on a delta of exactly zero.", "That the value is exact to two decimals, since a gross voi can be off only when the delta is not zero.", "Only that the entries average back to the stated chance; the card still reads 19.89 against 19.84 at full precision."]'::jsonb, 3, 'The check compares implied against stated chances and nothing else: on the EKPAN lottery, rounding to one decimal happened to average back exactly while still moving the gross voi from 19.84 to 19.89.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 8, 'Having seen 65.000000 / 9.000000 print the same 20.51 as 65.000000 / 10.000000 on the EKPAN lottery, a user types the posterior after No bright spot as 8.000000 percent. What does the Analyzer show?', '["20.51 again, since the posterior after No bright spot multiplies a Do Not branch worth 0 and cannot move any output of the Analyzer.", "18.46, since lowering either posterior lowers the value of information, as the row typed 64.000000 / 10.000000 already shows.", "EMV without information 75.75 and EVPI 52.00 only, because the implied success chance falls to 0.342200.", "A refusal saying the outcome chances given No bright spot fail to sum to 100 percent, since 8 percent sits below the allowance."]'::jsonb, 2, 'On the EKPAN lottery the delta of -7.800000e-3 is past the 0.005 allowance, so the value is withheld: a posterior that never reaches the value still breaks the agreement every value depends on. The entry is still a distribution, so it is withheld and not refused.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 9, 'With the EKPAN lottery posteriors at 65.000000 and 10.000000, Bright spot typed at 45.000000 percent passes at an implied 0.347500, and typed at 47.000000 percent fails at 0.358500. Why does the indicator chance move the implied prior fastest?', '["It weights both posteriors at once, shifting weight from one reading''s success chance to the other''s.", "It is the only entry the check reads, because the posteriors enter the value of information and never the implied prior.", "Indicator chances are typed in whole percents and posteriors to six decimals, so each step on an indicator chance is coarser.", "The Analyzer rescales the indicator chances to sum to 100 after every edit, which doubles the effect of any change to one of them."]'::jsonb, 0, 'On the EKPAN lottery a point of indicator chance moves weight across the whole gap between 65 and 10 percent, so 45.000000 prints 18.41 and 47.000000 is withheld; rounding 65 up to 66.000000 fails too, at 0.357600.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 10, 'Before the EC4-0 repair the published contradictingPosterior case printed a gross voi of 75.00 beside an EVPI card of 63.00. Why was that value impossible?', '["The survey cost of 10.0000 was added to the with side where it should have been subtracted, which lifted the gross value past its ceiling.", "The with side averaged to a 0.420000 success chance against a stated 0.300000, so the subtraction included the uplift of believing in a better prospect.", "The EVPI card came from the two action form and the voi from a lottery with a farm-out, so the two numbers described different lotteries.", "EVPI caps expected value with information and not the value of information, so 75.00 above 63.00 was ordinary arithmetic on consistent inputs."]'::jsonb, 1, 'Information derived by Bayes satisfies 0 <= evii <= evpi; 75.00 set a 0.420000 prospect after the survey against a 0.300000 prospect before it. It is history, and the repaired Analyzer withholds the value.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 11, 'A reviewer proposes fixing the pre-repair Analyzer by capping any value of information at EVPI. Why does that not fix it?', '["Clipping would change the verdict sentence, which is computed from the unclipped value, so the card and the sentence would disagree.", "EVPI is itself withheld whenever the inputs contradict each other, so there would be no ceiling left to clip the value against.", "Capping 75.00 at 63.00 is what the repaired Analyzer already does, so the proposal duplicates the repair rather than adding to it.", "Contradictions also land below the ceiling: the EKPAN lottery typed with indicators at 56 and 44 percent printed 40.62 under an EVPI of 52.00."]'::jsonb, 3, 'The honest value on those EKPAN lottery entries is 19.84, and indicatorChancesAboveHundred printed 33.00, the very card the consistent defaults print; a test on the output catches only the loudest cases, so the repair tests the inputs.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 12, 'The published pricey case prints a netVoi card of -17.00 today, and IRRI printed a gross voi of -15.00 before the repair. What separates the two?', '["Nothing of substance: a misleading survey has a negative gross value just as an expensive survey has a negative net value.", "The first is a pre-repair card and history, while the second is what the repaired Analyzer prints for IRRI today.", "The first says a price of 50.0000 exceeds a gross value of 33.00; the second could only come from typed inputs that contradict the stated prior.", "Both say the survey costs more than it adds, and they differ only in whether the survey cost of 10.0000 was deducted."]'::jsonb, 2, 'A decision maker can always ignore a Bayes signal, so evii is at least 0, and uselessSignal sits on that floor at 0.0000; a negative net value says the price is too high, a negative gross value says the inputs disagree.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 13, 'posteriorsAboveHundred types outcome chances given Positive Seismic that sum to 130 percent; IRRI types two readings whose outcome chances each sum to 100. How does the repaired Analyzer treat each?', '["It refuses the first before computing anything, and withholds the value on IRRI while still showing 15.00 and 63.00.", "It withholds both, keeping EMV without information and EVPI, because every contradiction in typed percents is reported the same way.", "It clips the first to 100 percent and values it at the pre-repair 69.00, and it withholds the value of information on IRRI.", "It withholds the first with a warning naming 130 percent, and refuses IRRI because its two readings are typed identically."]'::jsonb, 0, 'A refusal says the typed numbers are not chances at all, with the message "Outcome chances given "Positive Seismic" sum to 130 percent, expected 100"; a withholding says they are chances that cannot all be true together.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 14, 'Why can typed inputs contradict each other in the VOI Analyzer when the Decision Tree Builder''s information tree cannot?', '["The Builder rounds posteriors to six decimals and the Analyzer to two, and only the coarser rounding can break the half percent check.", "The Analyzer takes posteriors as typed, while the Builder derives them from likelihoods and the stated prior, so they agree by construction.", "The Builder refuses any survey whose readings disagree with the prior, while the Analyzer accepts them and repairs the posteriors afterwards.", "The Analyzer takes likelihoods where the Builder takes posteriors, and a likelihood typed in is compared against the wrong prior."]'::jsonb, 1, 'Averaging Bayes posteriors over the readings returns the prior, as the EKPAN lottery''s 0.460000 x 0.646739 + 0.540000 x 0.097222 = 0.350000 shows; nothing ties typed posteriors to outcome chances typed two boxes earlier, which is why the IRRI warning points to the Builder.'),
  ('decision', 'advanced', 'module', 'm01-inputs-that-contradict-each-other', 15, 'Before the repair, indicatorChancesAboveHundred, with indicator chances summing to 110 percent, printed a gross voi of 33.00. What made that value dangerous, and what happens to the entry today?', '["Nothing, since rescaling indicator chances by their sum leaves the posteriors alone, and the Analyzer still prints 33.00.", "It sat inside the half percent allowance, so the check passed it, and today the allowance is narrowed to catch it.", "It contradicted the stated chances, so today the value is withheld and EMV without information 15.00 and EVPI 63.00 remain on the screen.", "It matched the card the consistent defaults print; today it is refused with \"Indicator chances sum to 110 percent, expected 100\"."]'::jsonb, 3, 'A 110 percent indicator set is not a distribution, so it is refused outright and never reaches the consistency check; an output test would have passed 33.00, which sat under 63.00.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 1, 'On the published three outcome, four action lottery, Drill alone is rolled back by weighting 500.0000, 150.0000 and -20.0000 and subtracting its 60.0000 cost once, giving 109.0000. Why is that right here and wrong on the published chanceRootWithBranchCosts tree?', '["Here the payoffs are already discounted, while that tree''s branch costs fall later and must be discounted before they are charged.", "Here there is no chance node, while a chance node always charges its costs after weighting, which the tree then fails to do.", "Here the cost belongs to the action and is paid in every outcome; there each branch carries its own cost, paid only on that branch.", "It is right on both, and the -3.0000 printed for that tree is the engine charging each cost twice, once on the branch and once at the root."]'::jsonb, 2, 'On chanceRootWithBranchCosts calm is worth 19.0000 less 2.0000 and storm -25.0000 less 8.0000 before weighting, giving -3.0000; subtracting both costs after weighting gives a wrong -8.6000.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 2, 'With the outcome known first, the published golden records the best actions for Large, Medium and Dry on the three outcome lottery as indices 0, 0 and 2. Why does Dry record Farm out?', '["Farm out and Relinquish both pay 0.0000 in Dry, and the strictly greater comparison keeps the one listed first.", "Farm out breaks the tie by its better payoffs in Large and Medium, which the engine consults when two actions pay the same in one outcome.", "Relinquish is left out of perfect information because it pays nothing in any outcome, so Farm out is the only costless action there.", "Farm out is what the engine recommends at the prior once a well is dry, and perfect information repeats it."]'::jsonb, 0, 'Listed the other way round the golden would name Relinquish and evWithPerfect would stay at 133.0000, since EVPI takes the best value per outcome.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 3, 'The three outcome lottery has emvPrior 109.0000, evWithPerfect 133.0000 and an EVPI of 24.0000. Where does that 24.0000 come from?', '["Every outcome gains, since knowing Large in advance lets the engine size the well, and those gains add up across all three outcomes.", "Medium changes the action to Drill with partner, whose halved loss is worth 24.0000 once the outcome is known before the choice.", "It is Drill alone''s value less Drill with partner''s, 109.0000 less 54.5000, scaled down by the chance that the well comes up dry.", "Only Dry changes the action, from Drill alone to Farm out, so perfect information saves Drill alone''s net loss in the 0.300000 of dry cases."]'::jsonb, 3, 'In Dry Drill alone pays -20.0000 less its 60.0000 cost where Farm out pays 0.0000; that saving weighted by 0.300000 is 24.0000, and Large and Medium still choose Drill alone.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 4, 'A reader wants to value a survey on the three outcome, four action lottery in the VOI Analyzer. What does the Analyzer''s form do to the lottery?', '["It refuses the lottery with a message naming the number of actions, since the form accepts exactly two and this lottery has four.", "It keeps the named decision at its cost and Do Not paying 0, so Farm out and Drill with partner are lost on the way in.", "It keeps all four actions and values the survey against Drill alone, the best action at the prior at 109.0000.", "It merges Drill with partner into Drill alone, since one is a half scale copy of the other, and keeps Farm out beside them."]'::jsonb, 1, 'The Analyzer offers exactly two actions. On the EKPAN lottery a missing farm-out cut the survey''s gross value from 24.8250 to 19.8375, and the Analyzer''s 19.84 is that two action number.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 5, 'On the published threeByThree survey, Bright has likelihoods 0.700000, 0.300000 and 0.100000 given Large, Medium and Dry, at priors 0.200000, 0.500000 and 0.300000. What is the posterior chance of Large after Bright?', '["0.700000, since the chance of Bright given Large is the chance of Large once Bright has been seen.", "0.437500, the joint 0.200000 x 0.700000 divided by the chance of Bright, 0.320000.", "0.320000, the chance of Bright itself, which Bayes assigns to the outcome that the reading favours most.", "0.200000, since a reading cannot move a prior stated before the survey was run, only the action taken after it."]'::jsonb, 1, 'The chance of Bright is 0.200000 x 0.700000 + 0.500000 x 0.300000 + 0.300000 x 0.100000 = 0.320000; reading the likelihood 0.700000 as the posterior is the likelihood for posterior mistake.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 6, 'On threeByThree the Bright row of likelihoods, 0.700000, 0.300000 and 0.100000, does not sum to 1. A reviewer rescales that row before running the engine. What is the result?', '["The engine would have refused the unscaled survey for a row sum above 1, so the rescaling is what lets the survey be valued at all.", "The survey is worth more, since a rescaled row lowers the chance of Bright and so raises the posterior chance of Large after it.", "Nothing changes, because the engine rescales every likelihood row to 1 itself before applying Bayes to each of the readings.", "The row never needed fixing: rows are not distributions, and rescaling it breaks three likelihood columns the engine then refuses."]'::jsonb, 3, 'Each outcome''s column sums to 1 because the survey returns some reading whatever the outcome; the engine refuses a column that misses 1 and names it, and it never checks rows.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 7, 'On threeByThree, Drill alone after a Bright reading is worth 227.1875 against 109.0000 at the prior, and the survey costs 12.0000. Is the survey worth buying?', '["No: it is worth 1.2000 gross and -10.8000 net, because Bright and Flat lead to Drill alone, the action the prior already chose.", "Yes: the gain after Bright, weighted by its 0.320000 chance, alone exceeds 12.0000 before Flat and Dim add their share.", "Yes: the posterior chance of Large more than doubles after Bright, and a survey that moves posteriors that far earns its price.", "No, but only because its EVPI of 24.0000 caps any survey below twice its price, whatever the readings do to the choice."]'::jsonb, 0, 'EV with information is 0.320000 x 227.1875 + 0.380000 x 86.5789 + 0.300000 x 15.3333 = 110.2000, only 1.2000 above emvPrior; all of it comes from Dim, the one reading that moves the action to Farm out.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 8, 'The published threeByThreeCost12 information tree has root branch values 98.2000 and 109.0000 and chooses No further information. What is 98.2000?', '["The value of drilling after Bright and Flat alone, since the acquire branch drops the Dim reading that leads away from Drill alone.", "The acquire branch before its cost, which the tree compares against the prior after charging the survey cost to the other branch.", "EV with information, 110.2000, less the survey cost of 12.0000.", "The best reading''s value, 227.1875, weighted by the chance of Bright and added to the prior value of the other two readings."]'::jsonb, 2, 'The gap between the root branches, 98.2000 against 109.0000, is netEvii -10.8000, so a tree asked whether to buy the survey at 12.0000 declines it.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 9, 'On the published impossibleSignal case, the Never reading has likelihoods 0.000000 / 0.000000 and reports posterior 0.300000 / 0.700000, best action Drill and emv 43.0000. A report says the right move on a Never reading is Drill, worth 43.0000. What is wrong with it?', '["Nothing is wrong: a reading that carries no evidence leaves the prior in place, as a coin toss would, and the prior''s best action is Drill.", "The row is residue of a division by zero the engine should have refused, so the 43.0000 carries no meaning of any kind.", "The emv is wrong: after a reading that costs nothing, Drill should carry 115.3333, the value after the best reading.", "No outcome produces the reading, so its pSignal is 0.000000 and the row is the engine''s fallback to the priors for an event that never occurs."]'::jsonb, 3, 'Bayes cannot divide by a reading chance of 0, so the engine keeps the priors, the prior best action and the prior''s emv; 43.0000 describes an event with probability 0.000000, and no separate warning is given.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 10, 'impossibleSignal returns evWithInfo 55.5000 and evii 12.5000, the same as the published seismicBayes case, which is the same survey without the Never reading. Why?', '["The Never row''s emv is weighted by its pSignal of 0.000000, so it adds nothing to EV with information.", "The engine drops any reading whose likelihoods are all zero before valuing, so both cases reach Bayes as the same input.", "The Never emv of 43.0000 equals emvPrior, so at any weight it adds to EV with information exactly what emvPrior subtracts.", "A survey is valued from its likelihood column sums alone, and a zero row leaves every one of those column sums where it was."]'::jsonb, 0, '0.450000 x 115.3333 + 0.550000 x 6.5455 + 0.000000 x 43.0000 = 55.5000; the extra row changes the table and not the value.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 11, 'A reviewer expects the engine to refuse impossibleSignal, since the Never reading''s likelihoods are 0.000000 given both outcomes. What does the engine do?', '["It refuses the survey, naming the Never reading, because its posterior would need a division by a reading chance of exactly zero.", "It accepts the survey but prints a warning beside the table saying that the Never reading is impossible and was set aside from the value.", "It accepts the survey, because each outcome''s likelihood column still sums to 1, and gives no sign beyond the zero pSignal.", "It refuses the survey with a column message, since a column containing a zero likelihood cannot sum to 1 within 1e-6."]'::jsonb, 2, 'Never contributes 0 to both columns, so they sum to 1 as before; the likelihood refusal is for a column that misses 1, and a pSignal of 0.000000 is the only mark of an impossible reading.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 12, 'At a Large chance of 0.300000 on the three outcome lottery, Drill alone is worth 161.0000 and Drill with partner 80.5000. Why can the partner never be the best action on this lottery?', '["It is dominated by Farm out in every outcome, since Farm out pays at least as much as the partner in Large, Medium and Dry alike.", "Its payoffs and cost are exactly half of Drill alone''s, so it is worth half at every probability, and when half is negative Farm out, never below 0, beats it.", "It is never best at the stated prior, but at a Large chance of 0.000000 it halves Drill alone''s loss and so leads the other actions.", "It could lead if the engine''s risk aversion setting were raised, since halving the Dry loss is exactly what a cautious operator pays for."]'::jsonb, 1, 'Half of a positive value is smaller and half of a negative one is still negative; at a Large chance of 0.000000 Drill alone is 5.0000, the partner 2.5000 and Farm out 15.0000, and the engine has no risk aversion parameter.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 13, 'Large is swept on the three outcome lottery with Medium held at 0.5 and Dry taking the rest. How many times does the best action change across the sweep?', '["Once, from Farm out to Drill alone, between a Large chance of 0.000000 and 0.050000.", "Twice, from Farm out to Drill with partner and then from the partner to Drill alone, since the partner''s value rises more slowly.", "Three times, once for each adjacent pair of actions in the order listed, as each action overtakes the one before it.", "Once, from Relinquish to Farm out at a Large chance of 0.000000, since Relinquish and Farm out tie when nothing comes in large."]'::jsonb, 0, 'At 0.000000 Farm out leads at 15.0000 against Drill alone''s 5.0000, and at 0.050000 Drill alone leads at 31.0000 against 19.0000; the partner is always half of Drill alone and Relinquish never beats Farm out.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 14, 'Removing Drill with partner from the three outcome lottery changes no value, yet removing the farm-out from the EKPAN lottery cuts its survey''s gross value from 24.8250 to 19.8375. Why the difference?', '["A survey''s value scales with the prior value of the actions it can choose among, and the farm-out carries more of that value than the partner does.", "Both removals lower the value of information, but the lottery''s loss is too small to show once the engine rounds to four decimals.", "Removing an action changes a survey''s value only on a two outcome lottery, where every action is chosen after some reading.", "The EKPAN lottery''s farm-out is the best action after a No bright spot reading, while the partner is best after no reading and in no outcome here."]'::jsonb, 3, 'The test is whether an action is best after some reading or outcome; the perfect information indices 0, 0 and 2 never name the partner, so deleting it leaves 109.0000, 133.0000 and 24.0000 where they are.'),
  ('decision', 'advanced', 'module', 'm02-bigger-lotteries', 15, 'In Dry, Drill with partner loses 10.0000 plus its 30.0000 cost, where Drill alone loses 20.0000 plus 60.0000. Why does the engine give the halved loss no weight?', '["The Dry loss is already counted inside EVPI, so charging it again in the action values would count the dry outcome twice.", "It discounts the losing outcomes at the chance node, so a halved loss and a full loss both shrink toward the same small number.", "It is risk neutral and maximises the mean, with no utility function or risk aversion parameter that could prefer a smaller loss.", "It charges the partner''s cost before weighting and its payoffs after, so the halving cancels out of the comparison with Drill alone."]'::jsonb, 2, 'The rollback maximises expected money and applies no discounting, so a partner worth 54.5000 against 109.0000 at the prior loses; pruning it removes the one alternative that halves the exposure while changing no number.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 1, 'Decision Studio briefs the EKPAN tree as Optimal EMV 105.0000, Recommended first move Drill, Next best alternative 37.7500 and Decision advantage 67.2500. Which rows are engine returns?', '["All four, since the brief re-rolls the saved tree at brief time and reads each of the rows directly off the engine''s result.", "Only the Recommended first move, since Optimal EMV is copied from the answer the Decision Tree Builder stored with the tree.", "Every row except the advantage, since the engine returns Next best alternative as the second branch listed at the root.", "Optimal EMV and Recommended first move; the other two are arithmetic on the rollback."]'::jsonb, 3, 'On the EKPAN tree, next best is the largest other root branch value, Farm out at 37.7500, and the advantage is 105.0000 less 37.7500; the brief recomputes the saved tree rather than storing the Builder''s answer, so the two agree on the numbers.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 2, 'OKRIKA''s root branches, in the order listed, are Appraise 87.0000, Develop now 33.6000 and Sell now 48.0000. What does the brief print for Next best alternative and Decision advantage?', '["33.6000 and a larger advantage, since next best is the branch listed directly after the recommended first move.", "48.0000 and 39.0000, since Sell now is the largest other branch value even though it is listed third.", "25.0000, the sell value after a poor appraisal, the fallback inside the Appraise branch.", "183.6000 for Develop now, which places Develop now first and Appraise second, so the advantage runs against Appraise."]'::jsonb, 1, 'Next best means the largest other value wherever it sits in the list; 87.0000 less 48.0000 is 39.0000, and taking the second branch listed would overstate the advantage.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 3, 'A reader checks OKRIKA''s brief against the Decision Tree Builder''s drawing, whose labels show each node''s own EMV. Develop now''s chance node carries 183.6000. What goes wrong if that label is taken as the branch value?', '["Its 150.0000 cost is left off, so Develop now appears to be the best move with Appraise second, and the advantage runs the wrong way.", "Nothing goes wrong, because the drawing labels each node after the cost on the branch into it, which is the value the brief uses.", "Only Appraise''s figure shifts, to 105.0000 before its 18.0000 cost, widening the advantage without changing the recommended move.", "The label is rounded for drawing, so the reader''s advantage differs from the brief''s in the decimals while the rows otherwise agree."]'::jsonb, 0, 'Develop now''s branch value is 183.6000 less 150.0000, which is 33.6000; a node label is the value before the cost on the branch leading into it.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 4, 'The EKPAN information tree, built on the EKPAN lottery with a survey cost of 8.0000, briefs as Optimal EMV 92.5750, Acquire CSEM survey, Next best alternative 75.7500 and Decision advantage 16.8250. What is the advantage?', '["The survey''s gross value before its cost of 8.0000, which is why the tree still chooses to acquire the survey at that price.", "The value of perfect information on the EKPAN lottery less the survey''s cost, the most the survey could still add.", "The survey''s net value, since the acquire branch is EV with information less the cost and the other branch is the prior EMV.", "The chance weighted gain from the No bright spot reading alone, the one reading that moves the action away from Drill."]'::jsonb, 2, 'On the EKPAN information tree, 100.5750 less 8.0000 is 92.5750, and 92.5750 less 75.7500 is 16.8250, exactly netEvii; the gross value is 24.8250, the price at which the two root branches would tie.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 5, 'The published equalEmvTie has root branches A 30.0000, B 30.0000 and C 29.9990, and the brief prints Recommended first move A with a Decision advantage of 0.0000. Why A?', '["It is listed first, and the engine replaces the best branch only when a later one is strictly greater.", "A was larger before rounding, and the advantage of 0.0000 is float residue left by subtracting two nearly equal values.", "C at 29.9990 sits closer to B, and the engine breaks a tie against whichever tied branch has the nearer runner up.", "The brief picks the branch with the least exposure among tied values, and A carries the smallest downside of the three."]'::jsonb, 0, 'A and B are exactly equal, so an advantage of 0.0000 beside a named first move is a tie reported as a recommendation; the recommendation comes from listing order and says nothing about which branch is better.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 6, 'The brief prints chanceRootWithBranchCosts as Optimal EMV -3.0000 and Recommended first move Single path, with no Next best alternative or Decision advantage row. What does that mean?', '["The brief failed to find a second branch, and the two missing rows should be worked out by hand from the calm and storm branches.", "The engine picked calm as the single path, since it is listed first and carries the higher branch value of 17.0000.", "The brief hides both rows whenever the Optimal EMV is negative, because a losing tree has no alternative worth quoting.", "The root is a chance node, so there is no choice to recommend or compare, and Single path is not a branch the engine picked."]'::jsonb, 3, 'The Builder writes Chance root and N/A for the same tree, and singleBranchDecision likewise prints just 7.0000 and the move named only; allNegative, at -52.0000, still prints a next best of -55.0000 and an advantage of 3.0000.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 7, 'Checking the brief''s -3.0000 for chanceRootWithBranchCosts by hand, a reader weights calm 0.600000 x 19.0000 and storm 0.400000 x -25.0000, then subtracts both costs, 2.0000 and 8.0000, and gets -8.6000. Which is right?', '["-8.6000, because the brief re-rolls only the optimal path, charging calm''s cost of 2.0000 and never the storm''s.", "-3.0000, because each cost is paid only on its own branch, so calm is worth 17.0000 and storm -33.0000 before weighting.", "-8.6000, because a chance root has no decision above it, so its branch costs are charged once to the whole node after weighting.", "Both, since -3.0000 is the Optimal EMV and -8.6000 is the Decision advantage the brief leaves out on a chance root."]'::jsonb, 1, '0.600000 x 17.0000 + 0.400000 x -33.0000 is -3.0000; subtracting every cost after weighting charges the storm''s 8.0000 in calm weather too.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 8, 'Two saved EPE runs give the success case the same mean NPV of 420, and one of them has a far lower low case. Each is linked in turn to the EKPAN tree''s success terminal and briefed. How do the two decision sections compare?', '["The wider run prints a lower Optimal EMV, since its NPV P90 low case pulls the drill chance node down before the cost is charged.", "The wider run prints a higher Optimal EMV, since its NPV P10 high case adds upside that the rollback credits to the drill branch.", "Both print Optimal EMV 105.0000 with Drill, since a risk neutral rollback never looks past the mean.", "Both print 105.0000, but the wider run''s advantage shrinks, measured against its low case."]'::jsonb, 2, 'A chance node is a probability weighted sum, so its expectation uses each payoff''s mean alone; on the EKPAN tree both runs give 105.0000 and an advantage of 67.2500, and no risk aversion parameter exists to reward the narrower spread.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 9, 'A reviewer replaces the EKPAN tree''s linked success payoff with its NPV P90 of 185.0000, typed as a fixed payoff, to be prudent. What happens?', '["The drill branch falls to 22.7500 below the farm-out''s 37.7500 and the choice flips, because a low outcome is averaged as if it were the mean.", "Nothing moves, because the rollback reads only a summary''s mean, and the brief restores the linked mean of 420 at brief time.", "The drill branch falls to 22.7500 and still leads, since the farm-out''s success payoff is scaled down by the same low case.", "The root becomes 37.7500 and that is the right answer for a risk neutral tree, which should be fed each run''s low case."]'::jsonb, 0, 'On the EKPAN tree, 0.350000 x 185.0000 + 0.150000 x 170.0000 + 0.500000 x -25.0000, less the 55.0000 drill cost, is 22.7500; the NPV P90 is the run''s low case and was never its expected payoff.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 10, 'A summary linked to a terminal arrives with an NPV P90 of 185, an NPV P50 of 390 and an NPV P10 of 710, and no mean. What does the engine do?', '["It rolls back with the NPV P50 of 390, taking the middle case as the best available stand in for the missing mean.", "It averages the three percentiles into a mean and rolls back with that, flagging the payoff as estimated in the brief.", "It rolls back with the NPV P90 of 185, the low case, as a conservative fallback, which flips the EKPAN tree to Farm out.", "It refuses with \"Distribution payoff has no finite mean\" and does not estimate one."]'::jsonb, 3, 'The engine will not guess a mean from percentiles, since the rollback needs the expectation and three percentiles do not fix it; on the EKPAN tree reading 390.0000 would have printed 94.5000.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 11, 'In the Decision Tree Builder a user unlinks the Monte Carlo run from the EKPAN tree''s success terminal. What does the terminal hold afterwards?', '["No payoff, which the engine reads as 0.0000, so the drill branch collapses and Farm out becomes the recommended first move.", "The copied mean, 420.0000, as a fixed payoff, so the tree still rolls back to 105.0000.", "The copied NPV P90 of 185.0000, since unlinking keeps the conservative copy of the run and discards the other two statistics.", "The run''s current mean, re-read once at the moment of unlinking, so the fixed payoff is up to date with any revaluation."]'::jsonb, 1, 'Linking stores a copy of the run''s NPV mean, P90 and P10 at the moment of linking; nothing re-reads the run, and unlinking keeps the mean as a fixed payoff.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 12, 'Every section of a Decision Studio brief carries a provenance line. What does the decision section''s line establish about an EKPAN tree briefed at 105.0000?', '["That the tree''s payoffs were discounted, since the provenance line records the rate the rollback applied at brief time.", "That every cost box held a typed value, since a cleared cost is refused before a tree can be saved for a brief.", "Which saved tree was rolled back, and nothing about whether its probabilities, payoffs or cost boxes are right.", "That the tree agrees with the economics section, since both sections are stamped when the brief is built."]'::jsonb, 2, 'The rollback applies no discounting and a cleared cost box is silently 0; the EKPAN tree''s drill branch worth 105.0000 still loses money with probability 0.500000, and the source is where checking starts.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 13, 'A brief''s economics section comes from an EPE Monte Carlo run revalued after it was linked into a tree, and its decision section re-rolls that tree at brief time. What can the page show?', '["A consistent page, since re-rolling at brief time re-reads every linked run before the decision rows are printed.", "A refusal in the decision section, since the brief detects that the run behind a linked payoff has changed since linking.", "The new run''s mean in the decision section and the old one in the economics section, since only the tree is refreshed.", "An NPV summary the tree never saw beside an Optimal EMV built on the older copied mean, with both provenance lines true."]'::jsonb, 3, 'Re-rolling recomputes the tree without refreshing what the tree copied, so the page disagrees with itself; linking the run again in the Decision Tree Builder brings the two sections back into line.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 14, 'Writing up the EKPAN tree with its linked summary, an analyst labels the numbers. Which labelling follows the course''s percentile convention?', '["NPV P90 185.0000 as the low case and NPV P10 710.0000 as the high case, with the 0.350000 success chance as a plain probability.", "A high case for the NPV P90 of 185.0000, because a larger percentile number marks a larger outcome, and a plain success chance.", "The low case for the NPV P90 of 185.0000, and the success chance written as a P35 so that readers can see it is uncertain.", "NPV P10 710.0000 as the low case, since only 10 percent of the runs fall below it, with a plain success chance."]'::jsonb, 0, 'Under the exceedance meaning P90 is the low case, which is why the brief''s economics rows read NPV P90 (low), NPV P50 and NPV P10 (high); a probability, likelihood or posterior never takes a P-label.'),
  ('decision', 'advanced', 'module', 'm03-the-decision-brief', 15, 'The EKPAN tree briefs with a Decision advantage of 67.2500. What does that number say?', '["That Drill beats Farm out by at least 67.2500 in every outcome, a margin of safety the farm-out cannot close in any case.", "That the drill branch''s mean exceeds the farm-out''s by 67.2500; the drill still loses money with probability 0.500000.", "That the drill''s probability weighted gains exceed its probability weighted losses by 67.2500 once the farm-out is set aside.", "That a survey on the EKPAN tree could add up to 67.2500 before the recommended first move would change to Farm out."]'::jsonb, 1, 'On the EKPAN tree it is 105.0000 less 37.7500, a difference of two means; after the 55.0000 drill cost the outcomes are 365.0000, 115.0000 and -80.0000, and 105.0000 is none of them.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 1, 'A chance node named "Three equal outcomes" pays 30, 60 and 90, and each of its three branches is typed as 0.333333. What does the rollback engine return?', '["An emv of 60.0000, because a sum of 0.999999 sits exactly 1e-6 from 1 and the tolerance on a chance node is inclusive at its edge, so the node passes.", "An emv of 60.0000, because the 1e-12 representation allowance added in the EC4-0 repair absorbs the binary residue on a probability sum as well as on an implied prior.", "A refusal, `Chance branch probabilities sum to 0.999999, expected 1`, because three copies of 0.333333 land a hair more than 1e-6 from 1 in binary and the sum check carries no allowance for that.", "An emv just under 60.0000, because the engine accepts the sum and weights the three payoffs by the thirds exactly as they were typed."]'::jsonb, 2, 'In binary the gap is 0.0000010000000000287557, just above 1e-6, so the node is refused while its message prints 0.999999; typed as 0.3333333 it rolls back to 60.0000. The 1e-12 allowance belongs to the implied-priors check alone, and whether to add one here is an open owner decision (finding EC4-8).'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 2, 'The published justInsideTolerance case states a success chance of 0.300000 and implies 0.305000. How does the repaired implied-priors check read it, and why?', '["Consistent true, because the delta, which is 0.0050000000000000044 in binary, is compared against 0.005 plus a 1e-12 representation allowance.", "Consistent false, because in binary floating point the delta is 0.0050000000000000044, which is above the 0.005 threshold by 4.3e-18, so even an inclusive comparison turns it away.", "Consistent true, because the engine rounds every delta to six decimals, 5.000000e-3, before comparing it with the threshold.", "Consistent true, because the repair widened the threshold to 6.000000e-3 so that cases on the old boundary stop flipping."]'::jsonb, 0, 'Compared against 0.005 alone the case would read false, which is what the engine did before EC4-0 (finding D1, now resolved). The allowance absorbs a 4.3e-18 overshoot and nothing of a size worth arguing about.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 3, 'A reviewer argues that since the EC4-0 repair added an allowance to the half percent check, an implied success chance of 0.306000 against a stated 0.3 ought to pass now. What does the Analyzer do with published withheldPastHalfPercent?', '["It prints a gross voi of 35.10, because the allowance moved the inclusive boundary far enough out to take in a delta just past half a percent.", "It refuses the inputs with a message naming the sum in percent, because a delta above half a percent means the typed chances are not a distribution.", "It prints every card with a consistency warning beside them, since the repair only annotates a value built on chances that disagree.", "It withholds the value of information, because the allowance is 1e-12 and a delta of 6.000000e-3 is inconsistent before and after the repair."]'::jsonb, 3, 'The Analyzer still reports EMV without information 15.00 and EVPI 63.00. The gross voi of 35.10 it printed for these inputs before the repair is history, a number built on chances that cannot all be true.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 4, 'One engine family holds two boundaries: a chance node''s probabilities must sum to within 1e-6 of 1, and an implied chance must sit within 0.005 of the stated one. What happens exactly at each edge?', '["Both edges hold, because the EC4-0 repair gave each of the two comparisons the same 1e-12 allowance for binary representation error.", "The implied-priors edge holds because of its 1e-12 allowance, while the sum edge has none, so thirds typed as 0.333333 are refused although their decimal gap equals the tolerance.", "Both edges fail, because binary rounding pushes a value sitting exactly on either threshold a hair past it and neither check makes any allowance for that.", "The sum edge holds because its message prints 0.999999, while the implied-priors edge fails at 0.305000 on 4.3e-18 of binary overshoot."]'::jsonb, 1, '0.305 less 0.3 evaluates to 0.0050000000000000044 and passes under the allowance; three copies of 0.333333 leave a gap of 0.0000010000000000287557 and are refused. Two boundaries in the same engine behave differently at their edge.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 5, 'Branch A pays 20 with its cost typed as "abc", and branch B pays 12 at no cost. What does the rollback return?', '["A refusal naming branch A, because the engine checks that every cost reads as a number in the same way that it checks every payoff.", "An emv of 20.0000 with A best and no message, because a cost that does not read as a number is charged as zero.", "An emv of 15.0000 with A best, because text typed on a cost is converted to the number the user most likely meant, which here is 5.", "An emv of 12.0000 with B best, because the engine drops a branch whose cost cannot be read and rolls back only what remains."]'::jsonb, 1, 'The intended reading at a cost of 5 is 15.0000, so the root is overstated by the whole cost while the first move still looks sensible. The check is arithmetic: a branch value equal to its child value means the cost was never charged.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 6, 'On the decision where A pays 20 at a cost of 5 and B pays 12, three slips are made one at a time: A''s cost typed as "abc", A''s cost typed as -5, and A''s payoff left empty. Which slip changes the recommendation?', '["The cost typed as \"abc\", because a branch carrying a cost the engine cannot read is valued at 0 and loses to B at 12.0000.", "The cost typed as -5, because the engine refuses a negative cost on A and B becomes the only branch it is able to roll back.", "None of the three, since each default leaves A ahead: 20.0000 for the text cost, 25.0000 for the receipt and 15.0000 for the empty payoff.", "The empty payoff, which is read as 0, so branch A becomes -5.0000 and B wins at 12.0000."]'::jsonb, 3, 'A missing payoff is the more dangerous default: "abc" lifts A to 20.0000 and -5 lifts it to 25.0000, both still best, while an empty or null payoff flips the choice. A payoff of "20abc", by contrast, is refused with `Terminal payoff is not a number`.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 7, 'Why is a cost typed as -5 on branch A, which pays 20, accepted and valued at 25.0000?', '["The engine reads a negative cost as money received, which is right for a farm-in carry and a typing error for everything else, and it cannot tell the two apart.", "The engine flags the negative cost as a receipt in its output, so the 25.0000 arrives with a note that a reviewer is expected to read before using it.", "The engine charges an unreadable cost as zero and then adds the typed magnitude back as a separate receipt on the same branch.", "A branch value is the child value plus its cost, so any cost typed on A adds to it and a cost of 5 would give the same 25.0000."]'::jsonb, 0, 'A branch value is the child value less the cost, so 20 less -5 is 25.0000, and nothing in the output marks it; a cost of 5 gives 15.0000. Only a reader who checks each branch value against the cost they meant will see it.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 8, 'In the Decision Tree Builder a user clears the probability box on the branch paying 10 of a two-branch chance node paying 10 and 30, and the branch paying 30 already reads 1. What happens?', '["The cleared box stores 0, the sum falls short of 1, and the node is refused with a message that prints the sum to six decimals.", "The cleared box keeps its last saved value until a new number is typed, so the node rolls back exactly as it did before the edit and the drawing keeps the old chance.", "The cleared box stores 0, the sum is still 1 so the check passes, and the node returns 30.0000 with the cleared branch gone from the weighting.", "The node returns 20.0000, because an empty probability is shared out equally with the other branch before the payoffs are weighted."]'::jsonb, 2, 'A cleared probability usually surfaces as a sum that is not 1 and is refused; it passes only when the other branches already sum to 1. The engine gives the same 30.0000 for a probability typed as an empty string beside a 1, and 20.0000 comes from typing one probability as the text "0.5" beside 0.5.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 9, 'The published refusal case puts a bad distribution at node "cc", two levels under the root, whose probabilities sum to 0.200000. What does the rollback return for the rest of the tree?', '["The root EMV with the faulty chance node valued at zero, and a message beside it naming \"cc\" as the node that was skipped over.", "The root EMV with node \"cc\" rescaled to sum to 1, since 0.200000 is a proportion the engine can normalise.", "Values for every branch that does not pass through \"cc\", with the best branch chosen from among those that could be rolled back.", "Nothing: the message names node \"cc\", and there is no root EMV, no best branch and no value for the healthy branches."]'::jsonb, 3, '`Chance branch probabilities sum to 0.200000, expected 1 (at node "cc")` is the whole answer. One bad node stops the tree, so the node label in the message is the only pointer to where the fault lives.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 10, 'The Bayes calculation behind EVII checks the likelihoods of the EKPAN lottery''s survey before it computes anything. Which numbers must sum to 1?', '["Each signal''s likelihoods across the outcomes, so a bright spot''s 0.850000 given Success and 0.250000 given a dry hole must together sum to 1.", "Each outcome''s likelihoods down its column across the signals, so the Success column reads 0.850000 for a bright spot and 0.150000 for none.", "The chances of the signals themselves, 0.460000 for a bright spot and 0.540000 for none, which the engine checks before any posterior.", "The posteriors after each signal, 0.646739 and 0.353261 after a bright spot, since those are the numbers the action is chosen on."]'::jsonb, 1, 'The survey passes because Success reads 0.850000 / 0.150000 and Dry hole 0.250000 / 0.750000. A Dry hole column summing to 1.200000 is refused with the outcome named; the signal chances and posteriors are derived, never typed.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 11, 'The EKPAN lottery is typed into the repaired VOI Analyzer with Bright spot at 46.000000 percent and No bright spot at 64 percent. What does the Analyzer show?', '["No cards at all, only the refusal `Indicator chances sum to 110 percent, expected 100`.", "EMV without information 75.75 and EVPI 52.00, with the value of information withheld because the indicators contradict the stated prior.", "A refusal stating the indicator sum as a fraction of 1 rather than in percent, the engine''s internal scale for every chance it checks.", "The cards for renormalised indicator chances, since the Analyzer rescales any indicator set that misses 100 before valuing the survey."]'::jsonb, 0, 'Indicator chances that are not a distribution are refused before anything is computed, with the sum in percent. Withholding with 75.75 and 52.00 is the answer for chances that do sum to 100 but contradict the stated outcome chances.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 12, 'IRRI types both indicators as 20 / 80 percent, and published indicatorChancesAboveHundred types indicator chances summing to 110 percent. How do the repaired Analyzer''s answers differ?', '["Both are refused with a message naming the sum in percent, because each set of typed percents fails the check before any card is drawn.", "Both are withheld with 15.00 and 63.00 reported, because each describes chances that the stated outcome chances cannot support.", "IRRI is withheld and still reports EMV without information 15.00 and EVPI 63.00, while the 110 percent case is refused and shows no card.", "IRRI is refused because its implied success chance of 0.200000 is not the stated 0.3, while the 110 percent case is withheld with two cards."]'::jsonb, 2, 'A refusal says the numbers are not chances at all; a withholding says they are chances that cannot all be true together. EMV without information and EVPI depend only on the stated outcome chances, so 15.00 and 63.00 survive a withholding.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 13, 'Before the EC4-0 repair, which input the Analyzer now refuses printed a gross voi that looked exactly like a genuine answer on its default study?', '["posteriorsAboveHundred, whose 69.00 sat close enough to the evpi card of 63.00 that nothing on the screen marked it out as a problem.", "chanceOutsideRange, whose -15.00 read as an ordinary survey priced above its worth rather than as a gross value below the floor of zero.", "indicatorChancesAboveHundred, whose 33.00 is the default study''s own voi, printed for indicator chances summing to 110 percent.", "missingOutcomeChanceCountsAsZero, whose 41.00 is the default study''s own EMV with information, so it looked familiar to anyone who ran the defaults."]'::jsonb, 2, 'These cards are history, reconstructed from engine calls. 69.00 is above the 63.00 ceiling and -15.00 is below zero, both impossible on sight; 33.00 is the default study''s genuine voi and could not be caught by eye, while its EMV with information is 38.00.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 14, 'Published posteriorsOffsetButPriorsAgree types outcome chances given Positive Seismic that sum to 110 percent, built so that the priors they imply equal the stated ones. Why does a reviewer who checks only the implied priors miss it?', '["The implied-priors test passes, and only the check that each set of outcome chances sums to 100 catches it, which the Analyzer runs first and refuses on.", "The implied-priors test is run on rounded posteriors, so an offset of 10 percent is absorbed inside the half percent tolerance before it can register at all.", "The reviewer''s test is the right one, and the Analyzer passes the case too, since priors that agree prove every typed number is a chance.", "The implied-priors test fails on this case, but the Analyzer reports that failure as a withholding, so the reviewer takes the missing cards for a refusal."]'::jsonb, 0, 'The refusal reads `Outcome chances given "Positive Seismic" sum to 110 percent, expected 100`. Before the repair the same inputs printed a gross voi of 42.50 beside an evpi card of 63.00, a plausible number built on percents that were not chances.'),
  ('decision', 'advanced', 'module', 'm04-refusals-and-silent-defaults', 15, 'Thirds typed as 0.333 on "Three equal outcomes", paying 30, 60 and 90, are refused. A user repairs the node by nudging the branch paying 90 until the sum reads 1. What is wrong with that repair?', '["Nothing, because the tolerance of 1e-6 exists precisely so a user can close a rounding gap on whichever branch is most convenient to edit by hand.", "It is refused again, because the engine compares each branch with the others and requires equal chances on a node whose payoffs are evenly spaced.", "It moves the EMV only in the sixth decimal, which the rollback does not print at four places, so the result still reads 60.0000.", "The node passes but no longer says the outcomes are equally likely, so the EMV moves off 60.0000 by whatever the nudge put on that branch."]'::jsonb, 3, 'The repair is to type every third to seven places: 0.3333333 on each branch sums to 1.000000 and rolls back to 60.0000. A nudge changes the chances unequally, which is a different tree that happens to pass the check.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 1, 'On the EKPAN lottery at a success probability of 0.35 the drill is worth 75.7500 and the farm-out 33.2500. What would make either decision module recommend the farm-out at these same payoffs and chances?', '["Setting a risk tolerance below the drill''s loss of 80.0000, which the rollback reads before comparing the two means.", "Nothing in either module, since both maximise expected money and neither holds a utility function or a risk aversion setting.", "The drill''s 0.650000 chance of losing money, since the engine demotes an action that loses more often than it wins.", "A higher discount rate on the drill''s success payoff, because the rollback applies the rate typed on each terminal before weighting."]'::jsonb, 1, 'The engine sees only the two means: 0.350000 x 365.0000 plus 0.650000 x -80.0000 is 75.7500. A preference for the farm-out belongs in words beside the tree, never hidden in a payoff quietly lowered until the farm-out wins.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 2, 'The EKPAN lottery''s survey has an EVII of 24.8250. With the survey the drill is chosen only after a bright spot, so the joint chance of drilling a dry hole falls from 0.650000 to 0.162500. How much of that fall is priced in the 24.8250?', '["All of it, because the posterior after a bright spot is built from the dry-hole joint chance and so carries the reduction in risk inside it.", "The part that falls on the no bright spot reading, since the farm-out chosen there with probability 0.540000 never loses on the well.", "Most of it, since EVII is the EVPI of 52.0000 scaled down by how far the survey cuts the chance of drilling a dry hole.", "None of it, because EVII is a difference of means and prices only the rise in expected money."]'::jsonb, 3, 'A risk averse buyer would pay more than 24.8250 for this survey, and the engine cannot say how much more. The 0.162500 is a joint chance; the posterior of a dry hole after a bright spot is 0.353261.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 3, 'A small tree values Drill at 40.0000 less a cost of 10.0000 and Farm out at 30.0000. Listed Drill first it recommends Drill; listed Farm out first it recommends Farm out. What decides the recommendation?', '["The listing order, because a decision node replaces its incumbent only on a strictly greater value, so the first of two equal branches is kept.", "Floating-point residue in the cost subtraction, which leaves one of the branches a few binary digits ahead depending on which is evaluated first.", "The branch with the lower cost, since the engine breaks an equal EMV in favour of the action that commits less money up front.", "The last branch evaluated, because a decision node overwrites its best choice whenever a later value is at least as large."]'::jsonb, 0, 'Both orderings return an emv of 30.0000, and only the label follows the order in which somebody typed the branches. Residue decides at a computed switch point such as 0.228571 on the EKPAN lottery; 40.0000 less 10.0000 is exactly 30.0000.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 4, 'In the VOI Analyzer, Success at 25 percent pays 200, Dry hole at 75 percent pays -50, and the decision cost is 12.5. The insight names ''Drill Exploration Well'' as the optimal decision beside an EMV without information of 0.00. Why that action?', '["Acting is worth a small binary residue above 0 once the cost is subtracted, and the Analyzer names whichever action leads by that residue.", "The Analyzer names the risky action whenever the net value is positive, and the netVoi card reads 20.00.", "Acting is worth exactly 0, the same as \"Do Not\", and the named decision is listed first, so it keeps an exact tie.", "The Analyzer compares its actions before charging the decision cost of 12.5, so drilling leads by that amount before any card is filled."]'::jsonb, 2, '0.25 x 200 plus 0.75 x -50 less 12.5 is exactly 0, and nothing on the screen says walking away is worth the same. The gross voi of 25.00 is large precisely because the prior decision is perfectly unsettled.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 5, 'A Decision Studio brief for published equalEmvTie prints Optimal EMV 30.0000 and Recommended first move "A". Which row shows that the recommendation is a tie?', '["Decision advantage, which reads 0.0000 because Next best alternative is also 30.0000.", "Recommended first move, which appends the tied branch \"B\" after \"A\" whenever two root branches share the optimal value.", "Next best alternative, which reads 29.9990 for \"C\" and so shows that the runner-up sits only a hair below the choice.", "Optimal EMV, which is printed without decimals when two branches tie so that a reader can see the value is shared."]'::jsonb, 0, 'Next best alternative is the largest other root branch value, "B" at 30.0000, while "C" is 29.9990. The advantage row is the only place the tie is visible, so read it before the first move.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 6, 'On the Analyzer''s default study the gross voi is 33.00. At a survey cost of 32.996 the netVoi card reads 0.00. What does the verdict sentence say?', '["The information exactly pays for itself, because the verdict reads the two-decimal card and the card says 0.00.", "Since this is positive, acquiring the information is financially advantageous, because the verdict tests the net value before it is rounded.", "No verdict at all, since the Analyzer drops the sentence whenever a card rounds to zero and leaves the choice to the reader.", "The information exactly pays for itself, because a net value within half a cent of zero falls inside the Analyzer''s neutral band."]'::jsonb, 1, '33 less 32.996 is a small positive amount: the card rounds it to 0.00 and the sentence tests its sign. Only at a cost of exactly 33.000 do the card and the sentence both say neutral; no neutral band exists.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 7, 'Priced at 33.004, the default survey shows -0.00 on its net value card. What is the sign telling a reader?', '["Nothing, since -0.00 and 0.00 are the same number on a two-decimal card and the verdict beside both of them reads value-neutral.", "That the survey cost was entered as a negative receipt, which the Analyzer marks with a sign on an otherwise zero card.", "That the consistency check found a small disagreement, which the Analyzer reports as a signed zero in place of withholding.", "That the net value before rounding is a small negative amount whose sign the rounding kept, which is why the verdict says the survey is not justified."]'::jsonb, 3, 'The cards are toFixed(2) strings: 33 less 33.004 is negative and prints -0.00, and the verdict reads that same value unrounded and writes negative. At 32.996 the card reads 0.00 beside a positive verdict.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 8, 'A netVoi card reads 0.00 and the verdict beside it says positive. What does a careful reader report?', '["That the survey is a positive investment, because the verdict tests the unrounded number and is therefore the more precise of the two readings.", "That the survey is value-neutral, because the card is what the Analyzer displays and a sentence can never be more precise than its card.", "That the survey is priced at its value, found by comparing the cost with the gross voi, since the cost that makes information neutral is the gross value, 33.00 on the default study.", "That the survey is worth buying at any cost below the evpi card of 63.00, since the ceiling bounds the price and the gross value only bounds the net."]'::jsonb, 2, 'Costs of 32.996 and 33.004 are indistinguishable in any real tender, so a verdict flipping between them reports the sign of a residue. On the EKPAN lottery''s full survey the neutral price is its gross 24.8250.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 9, 'A symmetric survey on the EKPAN lottery at accuracy 0.600000 moves the success chance after a "reads dry" result from 0.35 to 0.264151. Why is its EVII 0.0000?', '["Because an accuracy of 0.600000 is too close to a coin toss for the engine to run Bayes, so it reports the prior''s value in place of a posterior.", "Because 0.264151 is still above the drill against farm-out switch of 0.228571, so both readings lead to Drill and no action changes.", "Because the success chance after \"reads success\", 0.446809, rises by more than the other reading falls, and the two changes cancel in value.", "Because EVII is floored at zero, and the small negative value this survey really has is clamped to 0.0000 for display."]'::jsonb, 1, 'Weighting Drill''s value at each posterior by the chance of each reading returns Drill''s value at the prior, 75.7500. Beliefs moved and no decision did; the survey first changes an action at accuracy 0.645051.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 10, 'The same symmetric survey on the EKPAN lottery is worth 0.7250 at accuracy 0.650000. What changed from accuracy 0.600000?', '["A \"reads dry\" result now moves the success chance to 0.224771, below the switch of 0.228571, so that reading leads to the farm-out.", "A \"reads success\" result now moves the success chance to 0.500000, which makes Drill worth more after that reading than at the prior.", "The survey became more accurate than the prior of 0.35, and information is worth something once its accuracy beats the prior chance.", "The EVPI of 52.0000 began to pass through to the survey, which receives a share of it in proportion to its accuracy above one half."]'::jsonb, 0, 'The survey first changes an action at 0.645051, and just past it that single changed reading adds 0.7250. After "reads success" the action was already Drill, so a larger shift there adds nothing.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 11, 'At accuracy 0.550000 the engine returns an EVII of -1.42e-14 for the symmetric survey on the EKPAN lottery. How should that be read?', '["As a small genuine loss, because a survey this weak misleads often enough to cost a sliver of expected money whenever it is bought.", "As the mark of inputs that contradict each other, which the Bayes engine reports as a negative value where the Analyzer would withhold one.", "As the tie rule at work, because both readings lead to Drill and the engine subtracts the branch listed second from the branch listed first.", "As 0.0000, floating-point residue from subtracting two equal sums, printed as zero below 1e-9."]'::jsonb, 3, 'Information derived by Bayes can never be worth less than 0, and the Bayes engine derives its posteriors from likelihoods, so its inputs cannot contradict each other. Both readings lead to Drill, so the value is 0.0000.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 12, 'The published dominantAction lottery has Always paying 100.0000 / 50.0000 and Never paying 10.0000 / 5.0000, with an evpi of 0.0000. Why is perfect information worthless there?', '["The outcome is already certain, so nothing is left to learn and the value with perfect information matches the value at the prior.", "The signal''s readings do not depend on the outcome, so every posterior stays at the prior and no action is ever able to move.", "Never loses nothing in either outcome, so a decision maker can always fall back on it and information has no downside left to remove.", "Always is best in both outcomes, so knowing the outcome never changes the action, and evWithPerfect equals emvPrior at 65.0000."]'::jsonb, 3, 'Perfect information takes the best action per outcome, and that is Always both times. The certainOutcome lottery reaches 0.0000 another way, with emvPrior and evWithPerfect both 260.0000, and uselessSignal is an EVII of 0.0000.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 13, 'Published threeByThree has three readings and costs 12.0000; after "Dim" it recommends the farm-out, worth 15.3333. Why is its evii only 1.2000 against an evpi of 24.0000?', '["Its three readings split the 24.0000 of perfect information between them, and the \"Dim\" reading carries the smallest share of it.", "Its evii is reported net of the survey cost, so 1.2000 is what is left once most of the 12.0000 price is paid.", "It changes one action, on one reading, and is worth only what that single change adds, so its netEvii at 12.0000 is -10.8000.", "One of its readings is too unlikely to carry a posterior and is dropped, so only two readings contribute value."]'::jsonb, 2, 'Bright and Flat both still lead to Drill alone, so the survey adds nothing on those readings. Its gross 1.2000 is a tenth of the 12.0000 price, and the information tree chooses No further information.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 14, 'The EKPAN tree''s success payoff is linked in the Decision Tree Builder to a Monte Carlo summary with mean 420, P90 185, P50 390 and P10 710 (P90 the low case), and the run is revalued afterwards. What does the tree show?', '["105.0000 from the mean copied at the moment of linking, because only the mean enters and nothing re-reads the run until it is linked again.", "The revalued run''s mean, because the Builder re-reads a linked run every time the tree is rolled back so that the payoff stays current.", "A value between its P90 and P10 cases, because the rollback weights the three percentiles of a linked summary ahead of the chance node.", "37.7500 with the farm-out recommended, because a linked summary enters at its P90, the conservative case for an exploration payoff."]'::jsonb, 0, 'A linked summary is a copy taken at link time. Read at its P90 of 185 the EKPAN tree would fall to 37.7500 and flip to the farm-out; at the mean it is identical to a plain 420.0000 payoff, and the spread is carried and never used.'),
  ('decision', 'advanced', 'module', 'm05-numbers-to-distrust', 15, 'The EKPAN lottery''s survey typed into the VOI Analyzer gives a gross voi of 19.84, while the Bayes engine values the same survey at 24.8250. Which is correct?', '["24.8250 only, since the Analyzer rounds the posteriors it is given to whole percents and loses the difference in that rounding before valuing them.", "Both: 19.84 is the value when the only actions are the drill and \"Do Not\", and 24.8250 is the value with the farm-out available.", "19.84 only, because the Bayes engine values the survey before the drill cost of 55.0000 is charged and so overstates it.", "Neither, because a survey that changes the action after only one of its readings must be valued at its EVPI of 52.0000."]'::jsonb, 1, 'The Analyzer offers exactly two actions; with Farm out removed the Bayes engine gives an evii of 19.8375, which is the 19.84. The Analyzer values one survey before one decision and has no place for a third action.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 1, 'IRRI types both of the Analyzer''s indicators as 20 / 80 percent against stated outcome chances of 30 / 70. What does an expert reading write down?', '["A value of information of -15.00, worked out by hand from the typed chances, since the repaired Analyzer no longer prints one.", "A value of information of 0.00, since a withheld value means the survey cannot change the decision and so is worth nothing.", "No numbers at all, because indicator chances that contradict the stated ones are refused before the Analyzer computes anything.", "EMV without information 15.00 and EVPI 63.00, with the value of information withheld because the inputs imply a success chance of 0.200000."]'::jsonb, 3, 'The two surviving cards depend only on the stated outcome chances. -15.00 is the gross voi printed before the EC4-0 repair, history and below the zero floor that Bayes guarantees, and a withheld value is never written as 0.00.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Before the EC4-0 repair, published certainPosteriorsWithheld printed a gross voi of 245.00. What made that number impossible on sight?', '["It sat below the default study''s genuine gross voi of 33.00, which any survey on those same payoffs must at least reach.", "It sat above the evpi card of 63.00, and no information can be worth more than perfect information.", "It turned negative once the survey cost of 10.0000 was taken off, and a net value below zero cannot come out of Bayes.", "Its implied success chance of 1.000000 lies outside the range the Analyzer accepts, so the value rested on an out-of-range input."]'::jsonb, 1, 'The inputs imply 1.000000 / 0.000000 against a stated 0.300000 / 0.700000, and the net value then was 235.00. The repaired Analyzer reports 15.00 and 63.00 and withholds the rest.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 3, 'The EKPAN lottery''s survey is typed into the Analyzer with its posteriors rounded to 65 and 10 percent, which passes with a gross voi of 20.51. What happens when they are rounded to 65 and 8 percent?', '["It passes with a gross voi of 20.51 as well, because rounding a posterior to a whole percent never moves the implied prior by half a percent.", "It is refused, because posteriors rounded to whole percents no longer sum to 100 under each indicator and so are not chances.", "The value of information is withheld, because the implied success chance is 0.342200, a delta of -7.800000e-3, outside the 0.005 check.", "It passes with a gross voi of 19.84, because the Analyzer recovers full-precision posteriors from the indicator chances before valuing."]'::jsonb, 2, 'At 65 and 10 the implied chance is 0.353000, within 0.005 of the stated 0.35; at 65 and 8 it is 0.342200 and the Analyzer withholds. 19.84 is the gross voi at full precision.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The first step of an expert case adds every set of typed percents. The EKPAN lottery typed with No bright spot at 64 percent fails it. What is the answer for that case?', '["The refusal message, `Indicator chances sum to 110 percent, expected 100`, and the box at fault, since a refused case has no value.", "EMV without information 75.75 and EVPI 52.00 with the value of information withheld, as for any typed inputs that fail a check.", "The values from the later steps with No bright spot corrected so that the pair sums to 100, since the message names the box that was mistyped.", "The gross voi the Analyzer printed before the repair, since a refused case is valued the way the Analyzer valued it before EC4-0."]'::jsonb, 0, 'The indicator chances sum to 110.000000 percent, so they are not a distribution. Withholding with 75.75 and 52.00 answers chances that sum correctly but contradict each other, and the message never says whether 64 or 46.000000 is the slip.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 5, 'In the second step an expert rebuilds the EKPAN lottery''s implied prior by hand from its survey. Which arithmetic is right?', '["0.850000 plus 0.150000 gives 1 down the Success column, so the stated prior of 0.350000 holds by construction.", "0.646739 and 0.097222 averaged equally over the two readings give the stated prior of 0.350000 to within the 0.005 check.", "0.460000 x 0.646739 gives 0.297500, 0.540000 x 0.097222 gives 0.052500, and the sum 0.350000 is the stated prior.", "0.297500 plus 0.162500 gives 0.460000, and that joint total is the implied prior the stated 0.350000 is compared against."]'::jsonb, 2, 'The implied chance of an outcome is the sum over the indicators of each indicator''s chance times the outcome''s chance given it. 0.297500 plus 0.162500 is the chance of a bright spot, and the likelihood columns are a separate check.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 6, 'An expert case lists a three-outcome lottery with Drill alone at 109.0000, Drill with partner at 54.5000, Farm out at 31.0000 and Relinquish at 0.0000. Why can Drill with partner never be the best action at any probability?', '["It falls below Farm out once the Large chance drops under 0.200000, and above that chance Drill alone overtakes it, so no window is left.", "Its partner''s share is charged as a cost after weighting, which pulls the value below Relinquish whenever the Dry chance exceeds 0.300000.", "It becomes best only at a Large chance of 0.500000, which the sweep never counts because the Dry chance would then be 0.000000.", "It is exactly half of Drill alone everywhere: half of a positive value is smaller, and half of a negative one is still negative while Farm out never falls below 0."]'::jsonb, 3, 'The sweep holding Medium at 0.5 has one switch, between Farm out and Drill alone; at a Large chance of 0.000000 Drill with partner is 2.5000 against Farm out at 15.0000. The third step still lists it, valued.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 7, 'In the fourth step, perfect information on the EKPAN lottery needs the best action after a dry hole, where Farm out and Walk away both pay 0.0000. Does that tie change the EVPI?', '["Yes: the tie goes to Farm out as the branch listed first, and its 95.0000 on a success lifts the expected value with perfect information.", "No: EVPI takes the best value per outcome, so 0.350000 x 365.0000 gives 127.7500 and, less 75.7500, the EVPI is 52.0000 whichever is named.", "Yes: at a tie the engine averages the two tied actions, which halves the contribution of the dry hole to the value with perfect information.", "No, but only because Walk away is dropped from a lottery where the farm-out pays at least as much in every outcome, so no tie exists."]'::jsonb, 1, 'Both tied actions pay 0.0000 on a dry hole, so 0.650000 x 0.0000 adds nothing whichever is named. A tie changes a label and never the value taken.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 8, 'On the EKPAN lottery an expert values the survey at a cost of 8.0000. Which set of figures belongs in the report?', '["Gross 24.8250, net 16.8250, a neutral price equal to the gross 24.8250, and bounds of 0 and 52.0000 on the gross.", "Gross 24.8250, net 16.8250, and a neutral price of 52.0000, since information stays worth buying until its cost reaches the EVPI ceiling.", "Gross 16.8250 and net 8.8250, since the survey cost is taken off once inside the information tree and again when the net is reported.", "Gross 100.5750 and net 92.5750, since the value of information is the expected value with the survey before the prior is subtracted."]'::jsonb, 0, 'EVII is 100.5750 less 75.7500. The information tree''s two root branches tie at a survey cost of 24.8250, where the engine keeps the acquisition as the branch listed first.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A case asks what the EKPAN lottery''s survey is worth with all three of its actions available, and a candidate writes the Analyzer''s gross voi of 19.84. What went wrong?', '["The right number for the wrong question: 19.84 is the two-action value, and with the farm-out available the survey is worth 24.8250.", "Nothing, because the Analyzer is the published tool for this question and its 19.84 supersedes a hand calculation on the Bayes engine.", "A rounding slip, since 19.84 is the Bayes engine''s 24.8250 after the posteriors are rounded to whole percents inside the Analyzer.", "The candidate quoted the net value, since 19.84 is what remains after the survey cost and the gross value sits in the guidance sentence."]'::jsonb, 0, 'The Analyzer offers only the named decision and "Do Not"; the Bayes engine without the farm-out gives 19.8375. The Analyzer''s netVoi card for the same survey reads 11.84 and its evpi card 52.00.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 10, 'An expert reads the EKPAN lottery survey''s likelihood of 0.850000, a bright spot given success, as the chance of success after a bright spot. What does that do to the drill after a bright spot?', '["Nothing to the value, because a likelihood and a posterior are the same number whenever the survey passes its consistency check.", "It values the drill at 207.7989 regardless, because the engine converts any typed 0.850000 into the posterior before weighting the drill.", "It values the drill at 298.2500 in place of 207.7989, because the posterior after a bright spot is 0.646739.", "It lowers the drill after a bright spot to 9.2361, since that likelihood belongs to the reading on which the farm-out is chosen."]'::jsonb, 2, 'Bayes turns 0.850000 into 0.646739 because a bright spot also appears on 0.250000 of dry holes, which makes a bright spot 0.460000 likely overall. 9.2361 is the farm-out''s value after no bright spot.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 11, 'A Decision Studio brief for the EKPAN tree prints Optimal EMV 105.0000, Next best alternative 37.7500 and Decision advantage 67.2500, with the success payoff linked to a Monte Carlo summary. Read at the summary''s P90 of 185.0000, the low case, what would change?', '["Nothing, because the brief re-reads the linked run at brief time and the run''s mean has not moved since it was saved.", "The advantage would shrink by the gap between the mean and the P90, while Drill stayed the recommended first move.", "The tree would rise to 206.5000, because the P90 of a Monte Carlo summary is its high case under the exceedance convention.", "The tree would fall to 37.7500 and the choice would flip to the farm-out, though the brief rightly uses the mean, the only statistic a linear rollback needs."]'::jsonb, 3, 'With success at 185.0000 the drill branch is worth 22.7500 against the farm-out''s 37.7500. At the mean of 420 the brief''s 105.0000 is identical to a plain payoff, and 206.5000 belongs to the P10, the high case.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 12, 'OKRIKA appraises at 87.0000 against selling now at 48.0000. Without the option to sell after a poor appraisal, the appraisal branch would be worth 15.6000. What does the difference between 87.0000 and 15.6000 price?', '["The appraisal''s information, since 71.4000 is what appraising adds over developing now at 33.6000.", "The later choice: the option to sell after a poor result is worth 71.4000 inside the appraisal branch.", "The decision advantage, since 71.4000 is how far the recommended first move leads the next best alternative in the brief.", "The first move itself, since 71.4000 is what the root would lose if Sell now at 48.0000 were struck from the tree."]'::jsonb, 1, '87.0000 less 15.6000 is 71.4000. Without the later choice the root would sell now at 48.0000, and with it the brief''s Decision advantage for Appraise is 39.0000.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 13, 'The story so far says thirds typed as 0.333 are refused while 0.3333333 rolls back to 60.0000. Where do thirds typed to six places, 0.333333, fall?', '["Accepted at 60.0000, because the message would print 0.999999, which is exactly 1e-6 short and inside a tolerance that includes its edge.", "Accepted at 60.0000, because the EC4-0 repair gave the chance node sum the same 1e-12 allowance that holds the half percent boundary.", "Accepted just below 60.0000, because the engine weights the payoffs by 0.333333 each and reports the slightly smaller mean.", "Refused, because in binary their sum misses 1 by 0.0000010000000000287557 and the chance node check makes no allowance for binary rounding."]'::jsonb, 3, 'Six places and fewer are refused and seven land inside 1e-6. The 1e-12 allowance belongs to the implied-priors check alone; adding one here is an open owner decision (finding EC4-8).'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 14, 'The half percent boundary on implied priors holds in the repaired check. What holds it?', '["A 1e-12 allowance on top of 0.005, which absorbs 0.0050000000000000044, the binary value of 0.305 less 0.3.", "An inclusive comparison against 0.005 alone, which suffices because 0.305 less 0.3 is exactly 0.005 in binary floating point.", "A threshold widened to 6.000000e-3, which is why an implied chance of 0.306000 is the first case the Analyzer withholds.", "Rounding each implied chance to six decimals before the delta is taken, so that 0.305000 less 0.300000 comes out exact."]'::jsonb, 0, 'The binary delta overshoots 0.005 by 4.3e-18, and before EC4-0 the engine had no allowance and called justInsideTolerance inconsistent (finding D1). An implied 0.306000 is inconsistent before and after the repair.'),
  ('decision', 'advanced', 'module', 'm06-the-expert-reading', 15, 'An expert writes one sentence reporting the EKPAN lottery''s survey. Which sentence carries everything the reading asks for?', '["Worth 19.84 gross in the Analyzer and 11.84 net, which is its value because the Analyzer is the published tool for this very question.", "Worth 24.8250 gross and worth buying at any cost up to its ceiling of 52.0000, since the EVPI is the price that makes information neutral.", "Worth 24.8250 gross and 16.8250 net at a cost of 8.0000, against a ceiling of 52.0000, with drill, farm-out and walk away as the actions.", "Worth 16.8250 as the value of the survey, since the cost of 8.0000 is already inside the information tree and needs no separate mention."]'::jsonb, 2, 'A value of information without its actions, its tree and its consistency is not a number: the same survey is 19.84 in the two-action Analyzer. The price that makes the survey neutral is the gross 24.8250, below the 52.0000 ceiling.'),
  ('decision', 'advanced', 'final', null, 1, 'The EKPAN lottery goes into the VOI Analyzer twice with its full-precision posteriors kept. In the first entry No bright spot is typed at 64 percent beside Bright spot at 46.000000 percent; in the second the indicators read 56 and 44 percent. What does each entry show?', '["Both are withheld in the same way, keeping EMV without information 75.75 and EVPI 52.00, because each entry breaks the agreement between the posteriors and the stated chances.", "The first is rescaled to 100 percent and valued as typed, and the second prints its gross voi of 40.62 in the guidance sentence with a consistency warning beside it.", "The first is refused with a message naming 110 percent and shows no card at all; the second keeps 75.75 and 52.00 and withholds the rest.", "Both are refused before anything is computed, since an implied Success of 0.404952 is as far from being a distribution as a sum of 110 percent is."]'::jsonb, 2, 'Percents that are not a distribution are refused and nothing is computed; 56 and 44 do sum to 100, so they are chances that contradict the stated 0.350000 (implied 0.404952), and only the two cards built on the stated chances survive.'),
  ('decision', 'advanced', 'final', null, 2, 'A report on IRRI copies the repaired Analyzer and writes the net value of information as 0.00 million USD, on the grounds that nothing was computed. Why is that line wrong?', '["A withheld value is not zero: the entries imply 0.200000 against a stated 0.300000, so there is no net value to quote, and the report should say it is withheld and why.", "It should read -25.00, the net value the same inputs give once the survey cost of 10.0000 is taken off the gross value of -15.00 that Bayes produces for them.", "It should read 23.00, the default study''s net value, because IRRI is the default study and a consistency warning changes the wording of the guidance and not the price.", "The zero is right but incomplete, since a net card of 0.00 means the survey is priced exactly at its gross value and the report must set the survey cost of 10.0000 beside it."]'::jsonb, 0, 'The repaired Analyzer shows only EMV without information 15.00 and EVPI 63.00 on IRRI. The -15.00 gross and -25.00 net are history from before the repair, and writing 0.00 reads a withholding as a card priced at its value.'),
  ('decision', 'advanced', 'final', null, 3, 'Two entries each sit exactly on the edge of their check in decimal: typed posteriors implying 0.305000 against a stated 0.300000, and three branches typed 0.333333 on the node "Three equal outcomes". What does the engine do with each today?', '["It accepts both, since the EC4-0 repair that resolved finding D1 gave every probability comparison in the engine the same 1e-12 representation allowance.", "It refuses both, because each lands a hair outside its tolerance in binary arithmetic, 0.0050000000000000044 for the first and a sum printed as 0.999999 for the second.", "It accepts the second, rounding a sum of 0.999999 to 1 before comparing, and refuses the first, because the half percent check is exclusive at its boundary.", "It accepts the first, because the half percent check adds a 1e-12 allowance, and refuses the second, because the 1e-6 sum test has no allowance for binary rounding."]'::jsonb, 3, '0.305 - 0.3 is 0.0050000000000000044 in binary and passes only by the 1e-12 allowance; three copies of 0.333333 miss 1 by a binary gap just above 1e-6, and that comparison was left strict (EC4-8, still open).'),
  ('decision', 'advanced', 'final', null, 4, 'A Decision Studio brief on a saved two-branch tree reads Optimal EMV 20.0000 with first move "A". Branch A pays 20 and was meant to carry a cost of 5; branch B pays 12. The provenance line names the saved tree. What does the brief tell a reader about that cost?', '["That it was charged, since the rollback refuses a cost that is not a number, and Decision Studio cannot brief a tree that the engine has refused to roll back at all, whatever its provenance line says.", "That it was never charged: A is worth exactly its payoff, which is what a cost typed as \"abc\", left empty or cleared in the Builder gives, and no line of the brief flags it.", "That it was typed as the text \"5\", which the engine reads as a number and which leaves branch A at its full payoff of 20.", "Nothing either way, because the brief prints each root value before the cost on its branch, so 20.0000 would appear whether or not the 5 was charged."]'::jsonb, 1, 'With the cost charged A is worth 15.0000; a non-numeric, empty or absent cost is charged as 0 and A reads 20.0000, and the brief re-rolls the saved tree with every silent default it carries.'),
  ('decision', 'advanced', 'final', null, 5, 'The published threeByThreeCost12 information tree is briefed in Decision Studio. Which decision rows does the brief print?', '["Optimal EMV 110.2000 on the acquisition, with a next best of 109.0000 and a Decision advantage of 1.2000, which is the gross value of the survey before its cost is paid.", "Optimal EMV 109.0000 on \"No further information\", a Next best alternative of 98.2000 and a Decision advantage of 10.8000, the size of the survey''s negative net value.", "Optimal EMV 98.2000 on the acquisition and a Decision advantage of -10.8000, which is the net value of the survey once its cost of 12.0000 has been paid, since a brief always leads with the acquisition.", "Optimal EMV 109.0000 with first move \"Drill alone\" and no next best row, because the root of an information tree is read as a chance node."]'::jsonb, 1, 'The root branches are 98.2000 for acquiring and 109.0000 for no further information, so the next best is 98.2000 and the advantage, 109.0000 less 98.2000, is the amount by which the survey fails to pay (netEvii -10.8000).'),
  ('decision', 'advanced', 'final', null, 6, 'The published equalEmvTie tree in a brief and the Analyzer tie case (Success 25 percent paying 200, Dry hole 75 percent paying -50, decision cost 12.5) each name a winner at an exact tie. Where can a reader see that it is a tie?', '["On both screens: the brief marks the first move as indifferent, and the Analyzer adds a consistency warning whenever its two actions are equal at 0.00.", "On neither, since both round the values to two decimals, so the tied branch and the one worth 29.9990 cannot be told apart from 30.0000 on either screen.", "In the Analyzer, as a net value of 20.00 equal to EMV with information, and in the brief, by naming A and B together as the first move.", "In the brief, a Decision advantage row of 0.0000; the Analyzer prints no margin, and its insight names ''Drill Exploration Well'' beside an EMV of 0.00."]'::jsonb, 3, 'Both apps keep whichever branch or action is listed first, because the comparison is strictly greater. Only the brief''s derived advantage row prints the zero margin; the Analyzer''s cards (0.00, 20.00, 20.00, 46.88) never compare its two actions.'),
  ('decision', 'advanced', 'final', null, 7, 'On the Analyzer''s default study one survey is tendered at 32.996 and another at 33.004. A reviewer reads both netVoi cards and both verdict sentences. What should the report say?', '["That both are priced at the gross voi of 33.00: the cards read 0.00 and -0.00 while the verdicts, which test the unrounded net value, split positive and negative.", "That the first is worth buying and the second is not, exactly as the verdict sentences state, since the unrounded net value is the more precise of the two readings.", "That both are value-neutral, as the cards say, because the verdict sentence is written from the rounded card and simply lags it by one step of rounding.", "That neither can be judged, because the Analyzer withholds the net value once the survey cost comes within 0.005 of the gross value."]'::jsonb, 0, 'The cards are two-decimal strings and the verdict reads the sign of a difference far smaller than any cost estimate resolves. The neutral price is the gross value, 33.00 here, so the survey is priced at its value.'),
  ('decision', 'advanced', 'final', null, 8, 'Three negative numbers came out of these tools: a gross voi of -15.00 for IRRI before the repair, an EVII of -1.42e-14 for the symmetric EKPAN lottery survey at accuracy 0.550000, and a netVoi card of -17.00 on the pricey case. Which signals inputs that cannot all be true?', '["All three, because a value of information below zero, gross or net, is impossible for a signal that the decision maker is always free to ignore and never has to act on.", "The -15.00 and the -1.42e-14, since both are gross values of information below the floor of zero, while the -17.00 is a net value and therefore a legitimate answer.", "Only the -15.00: a gross value derived by Bayes cannot fall below 0, while -1.42e-14 is float residue printed as 0.0000 and -17.00 is a price above the value.", "Only the -17.00, because the pricey case charges 50.0000 for a survey worth 33.00, and a value of information below its own cost means the typed chances disagree."]'::jsonb, 2, 'A negative net value says the price is too high; a negative gross value says the entries contradict the stated prior. The engine reports EVII residue below 1e-9 as 0.0000.'),
  ('decision', 'advanced', 'final', null, 9, 'The threeByThree posteriors come out of the engine''s Bayes step: after Bright, Flat and Dim, read with chances 0.320000, 0.380000 and 0.300000, Large stands at 0.437500, 0.105263 and 0.066667. Could posteriors built this way fail the implied-prior check that makes the Analyzer withhold a value?', '["Yes, because three readings carry three rounding errors, and with every posterior printed to six places the average drifts past the allowance of 0.005.", "Yes, whenever one of the readings never happens, since a posterior weighted by a pSignal of 0.000000 drops out of the average and counts as zero.", "Only when a reading changes the action, because the check weights each posterior by its best action.", "No: posteriors derived from likelihoods and the stated prior average back to that prior by construction, and here they return Large at 0.200000."]'::jsonb, 3, '0.320000 x 0.437500 + 0.380000 x 0.105263 + 0.300000 x 0.066667 is 0.200000, the stated Large. A contradiction needs posteriors typed by a person, which the Analyzer accepts and the Decision Tree Builder never asks for.'),
  ('decision', 'advanced', 'final', null, 10, 'In the engine, the published impossibleSignal case lists a reading "Never" with likelihoods 0.000000 / 0.000000. In the Analyzer, missingOutcomeChanceCountsAsZero leaves one outcome chance given Positive Seismic blank. How does each tool answer?', '["The engine accepts the survey, gives Never the priors as its posterior and returns evii 12.5000 with no warning; the Analyzer refuses, naming a sum of 60 percent.", "Both refuse, the engine because a reading with pSignal 0.000000 cannot be divided by, and the Analyzer because a blank entry lies outside the range of 0 to 100 percent.", "Both accept and count the blank as zero, the engine returning evii 12.5000 and the Analyzer printing a gross voi of 41.00 in its guidance sentence beside its EVPI card of 63.00.", "The engine refuses Never because its likelihoods sum to 0, and the Analyzer withholds the value while it keeps EMV without information 15.00."]'::jsonb, 0, 'Never adds 0 to each outcome''s column, so both columns still sum to 1 and pSignal 0.000000 is the only sign. The Analyzer checks every distribution in percent first; 41.00 is what it printed before the repair.'),
  ('decision', 'advanced', 'final', null, 11, 'Two prunings: Drill with partner is deleted from the published three-outcome, four-action lottery, and Farm out is deleted from the EKPAN lottery before its survey is valued. Which pruning changes a number?', '["Neither, because neither action is best at its stated prior, and an action that loses at the prior contributes nothing to EVPI or to EVII.", "Only the EKPAN lottery one: the farm-out is best after No bright spot, so the survey falls from 24.8250 to 19.8375, while the partner is best nowhere and nothing on its lottery moves.", "Only the partner one, since deleting a half-scale copy halves the EVPI of 24.0000, while the farm-out adds nothing that Drill or Walk away cannot match.", "Both, the partner''s removal pulling evWithPerfect below 133.0000 and the farm-out''s removal pulling the EKPAN lottery''s EVPI below 52.0000."]'::jsonb, 1, 'The test is whether an action is best after some reading or outcome. 19.8375 is the two-action value the Analyzer prints as 19.84, and without the farm-out the EKPAN lottery''s EVPI stays 52.0000.'),
  ('decision', 'advanced', 'final', null, 12, 'A cautious engineer replaces the EKPAN tree''s linked success payoff with the summary''s NPV P90 of 185.0000, typed as a plain number, to allow for risk. What has happened to the tree?', '["It has been made risk averse in the proper way, since the rollback now weights the low case, and Farm out at 37.7500 correctly reflects the downside of the drill.", "Nothing, because the rollback reads only the mean of a distribution payoff, so the tree still returns 105.0000 on Drill whatever plain number is typed into the box.", "A risk preference is now hidden in a payoff: the tree rolls back to 37.7500 on the farm-out, where the mean of 420 gave 105.0000 on Drill, and nothing shows why.", "The engine refuses the payoff, since a P-labelled figure typed where a mean belongs has no finite mean, and the rollback returns a message in place of any value for the tree."]'::jsonb, 2, 'Only the mean enters a linear rollback. A P90 (the low case) typed as the expected payoff gives a drill branch of 22.7500 and flips the root; the engine is risk neutral, so a preference belongs in words beside the tree.'),
  ('decision', 'advanced', 'final', null, 13, 'A brief built today shows an economics section from a Monte Carlo run revalued last week, beside an Optimal EMV for a tree whose success payoff was linked to that run a month ago. What can a reader assume about the two?', '["Nothing about agreement: the tree was re-rolled today, but from the copy of the NPV mean stored when the link was made, so its EMV can rest on an older mean.", "That they agree, because the decision section is rolled back at brief time and re-reads every linked Monte Carlo run before it prints the Optimal EMV row for the tree.", "That they agree, since Decision Studio refuses to assemble a brief whose linked run has been revalued at any point after the tree last took its copy of that run''s summary.", "That the EMV matches the NPV P50 row, which is the statistic the tree copies from a linked run as its payoff."]'::jsonb, 0, 'Linking stores a copy of the NPV mean, P90 and P10 and nothing re-reads the run. Both provenance lines are true while the page disagrees with itself, until the run is linked again.'),
  ('decision', 'advanced', 'final', null, 14, 'On OKRIKA the brief prints a Next best alternative of 48.0000. A reviewer expected Develop now there, because the Builder drawing labels its node with the node''s own EMV of 183.6000 and it is listed second. Who is right?', '["The reviewer: 183.6000 is the value the root compares for that branch, so Develop now should outrank Appraise at 87.0000, and the brief has misread the saved tree it re-rolled at brief time.", "The brief, but only because Sell now carries no cost, and the brief ranks the costless branches ahead of costed ones when choosing a next best.", "The brief: Develop now is worth 33.6000 once its cost of 150.0000 is paid, below Sell now at 48.0000, and next best means the largest other value wherever it is listed.", "The reviewer on the ordering, since the next best row is defined as the branch listed straight after the recommended move."]'::jsonb, 2, 'The drawing labels a node before the cost on the branch into it. 183.6000 less 150.0000 is 33.6000, so the advantage is 87.0000 less 48.0000, which is 39.0000.'),
  ('decision', 'advanced', 'final', null, 15, 'The published chanceRootWithBranchCosts tree is shown in a Decision Studio brief and on the Decision Tree Builder''s cards. What do the two surfaces show?', '["Both give -8.6000 and recommend the calm branch, whose value of 17.0000 beats the storm branch at -33.0000 by a Decision advantage of 50 shown on both of the surfaces.", "The brief gives -3.0000 with \"Single path\" as the route the engine picked, while the Builder refuses the tree outright because a chance node cannot sit at the root of a tree.", "Both give -3.0000 and write \"Single path\", with the next best row printed as 0.0000 because there is no alternative worth anything.", "Both give -3.0000; the brief writes \"Single path\" and prints no next best or advantage row, and the Builder writes \"Chance root\" with N/A on the other two cards."]'::jsonb, 3, 'A chance root offers no choice, so there is nothing to recommend or compare against. The -3.0000 charges each cost on its own branch before weighting; subtracting the costs after weighting gives -8.6000.'),
  ('decision', 'advanced', 'final', null, 16, 'A large tree has a single chance node, "cc", two levels below the root, whose probabilities sum to 0.200000. Every other branch is sound. What does the rollback return?', '["A root EMV built from the healthy branches, with \"cc\" dropped from the maximum and its message attached to the result as a warning for the reader.", "The message naming \"cc\" and the sum 0.200000, and nothing else: no root EMV, no best branch and no value for any healthy branch.", "A root EMV with the probabilities at \"cc\" rescaled to sum to 1, the printed sum of 0.200000 being the figure the engine corrected them from.", "A root EMV with \"cc\" weighted as typed, since the probability tolerance is enforced only on a chance node that sits directly under the root."]'::jsonb, 1, 'The engine returns "Chance branch probabilities sum to 0.200000, expected 1 (at node "cc")" and no number, so the node label is the only pointer to the fault.'),
  ('decision', 'advanced', 'final', null, 17, 'The same slip is made in two tools: outcome chances that add to 90 percent are typed into the repaired Analyzer, and priors that add to 0.900000 are passed to the Bayes engine. What does each return?', '["Both refuse with the fraction message, since the Analyzer hands its percent entries straight to the same Bayes check as the engine and simply prints whatever message it gets back on screen.", "The engine refuses, while the Analyzer rescales the outcome chances so that they add to 100 percent, values the survey on the rescaled chances and marks each of its cards as approximate.", "The Analyzer withholds the value of information and keeps EMV without information and EVPI on screen, while the engine, which has no withholding state of its own, refuses the priors outright.", "Each refuses before computing anything, the Analyzer with \"Outcome chances sum to 90 percent, expected 100\" and the engine with \"Outcome probabilities sum to 0.900000, expected 1\"."]'::jsonb, 3, 'Chances that are not a distribution are refused in both, and the repaired Analyzer names the sum in percent on a form that takes percent. Withholding is kept for distributions that contradict each other, as IRRI''s do.'),
  ('decision', 'advanced', 'final', null, 18, 'Two repairs are proposed: nudging one of three 0.333333 branches up until the sum reaches 1, and nudging typed posteriors until the implied prior lands at 0.305000. What do the two repairs share?', '["Each makes a check pass by bending the inputs it protects: the thirds stop being equal and the EMV leaves 60.0000, and the posteriors keep the contradiction behind 34.75, only less of it.", "Each is the documented repair, since the rollback expects one branch to absorb the rounding error and the Analyzer''s allowance exists for posteriors tuned onto its boundary on purpose by the person typing them.", "Neither changes a value, because the nudge in each case is smaller than the tolerance it clears, 1e-6 on the sum and 0.005 on the implied prior.", "Each is harmless for the thirds and harmful for the posteriors, because a sum nudged to 1 still weights the payoffs of 30, 60 and 90 equally."]'::jsonb, 0, 'Thirds typed to seven places, 0.3333333, roll back to 60.0000 without favouring a branch. A value accepted at 0.305000 is not certified: moving the default study there raised the gross voi from 33.00 to 34.75.'),
  ('decision', 'advanced', 'final', null, 19, 'A reviewer tests a typed survey only by averaging its posteriors back to the priors, and on posteriorsOffsetButPriorsAgree the implied chances match the stated ones. What does the repaired Analyzer do with that entry?', '["It values it normally, since the only test standing between typed posteriors and a value is the implied-prior check, and this case passes that check.", "It withholds the value of information and keeps EMV without information 15.00 and EVPI 63.00, the answer every failed check produces.", "It refuses it before any consistency test, because the outcome chances given Positive Seismic sum to 110 percent and are not a distribution.", "It prints a gross voi of 42.50 beside EVPI 63.00, because the allowance of 1e-4 percentage points covers a sum that misses by ten."]'::jsonb, 2, 'Each distribution is checked in percent first, so this case never reaches the implied-prior test. Before the repair the same entry printed 42.50, plausible and under the ceiling.'),
  ('decision', 'advanced', 'final', null, 20, 'Before the EC4-0 repair the Analyzer printed gross values of 245.00 for certainPosteriorsWithheld, 40.62 for the EKPAN lottery typed with indicators at 56 and 44 percent, and 33.00 for indicatorChancesAboveHundred. Which could a check on the output, between 0 and EVPI, have caught?', '["All three, because each differs from the value the same survey has when it is typed correctly, and an output check compares every printed figure against that value.", "Only the 245.00, above its EVPI of 63.00; 40.62 sits under 52.00 and 33.00 is the default study''s genuine value, which is why the repair tests the inputs.", "The 245.00 and the 40.62, since both exceed the honest EKPAN lottery value of 19.84, and an output check bounds each figure by the full-precision value of the survey.", "None of them, because a gross voi appears only in the guidance sentence and the CSV export, where no check of any kind is applied."]'::jsonb, 1, 'A bound on the output sees only values outside 0 to EVPI. 40.62 against 52.00 and 33.00 against 63.00 look ordinary, so the repaired Analyzer refuses or withholds on the inputs instead.'),
  ('decision', 'advanced', 'final', null, 21, 'The CSEM survey on the EKPAN lottery cuts the chance of drilling a dry hole from 0.650000 to 0.162500. How much of that reduction is inside its EVII of 24.8250?', '["None of it: EVII is a difference of expected money, and the engine has no utility function through which a smaller chance of loss could add value.", "All of it, because the engine turns each drop in the chance of loss into money at the drill cost of 55.0000 before it weights the two readings by their chances.", "About half, since a risk neutral engine counts a lower chance of loss at half the weight that a risk averse buyer of the same survey would give it in its own utility accounting.", "The part after a bright spot, where the joint chance of 0.162500 enters the posterior and lowers the drill''s value after that reading from 298.2500 to 207.7989."]'::jsonb, 0, 'Both modules maximise the mean. The fall from 0.650000 to 0.162500 is worth something to a company that cannot absorb a dry hole, and a risk averse buyer would pay more than 24.8250, by an amount the engine cannot say.'),
  ('decision', 'advanced', 'final', null, 22, 'At accuracy 0.600000 a symmetric survey on the EKPAN lottery drops the success chance after "reads dry" to 0.264151. A geophysicist calls it informative and asks for a price. What is it worth, and what would first give it value?', '["0.7250, because any move of the posterior away from 0.35 raises expected money in proportion to how far the posterior has moved.", "A small negative value printed as 0.0000, the residue of -1.42e-14, which disappears once the accuracy passes 0.650000.", "0.0000 until the accuracy reaches 1.000000, where it jumps to the EVPI of 52.0000, since imperfect information never changes an action.", "0.0000, because 0.264151 is still above the drill against farm-out switch of 0.228571; value first appears at accuracy 0.645051, when a dry reading can change the action."]'::jsonb, 3, 'Both readings still lead to Drill, so weighting Drill''s value at each posterior returns 75.7500, the value at the prior. By accuracy 0.650000 the survey is worth 0.7250.'),
  ('decision', 'advanced', 'final', null, 23, 'A tree that rolls back cleanly has payoffs typed as undiscounted revenue, and it is briefed in Decision Studio. Which part of the toolchain objects?', '["The rollback, which applies the discount rate saved with the tree to each terminal payoff before a chance node weights it.", "Decision Studio, whose provenance line marks a tree whose payoffs did not come from a cash flow engine such as Petroleum Economics Studio.", "None of it: neither module applies a rate, the rollback treats every payoff as money already discounted, and the provenance line names the tree without checking that.", "The Decision Tree Builder, which discounts each payoff at the rate saved with a linked Monte Carlo run before it rolls back."]'::jsonb, 2, 'The EKPAN tree''s 420.0000 and -25.0000 enter exactly as typed and roll back to 105.0000. A provenance line names a source; it does not certify that the payoffs are discounted.'),
  ('decision', 'advanced', 'final', null, 24, 'An expert case hands over typed Analyzer percents and asks what the survey is worth. In what order does the expert reading work it?', '["Read the Analyzer''s cards first, check each against its bounds of 0 and EVPI, and sum the percents only when a card falls outside those bounds.", "Sum each set of percents, rebuild the implied prior against 0.005, value every action without information, then perfect and imperfect information, and read the Analyzer''s cards last.", "Value the actions first, then rebuild the implied prior, and sum the percents only if the implied prior misses the stated one by more than 0.005.", "Run the Bayes engine on the typed posteriors, compare its EVII with the gross voi, and treat any gap wider than 0.005 as a refusal."]'::jsonb, 1, 'A refused case has no value and a withheld one has only two numbers, so chances and their agreement come before any value; the tool comes last, where a two-action card or a card near zero is read against the actions and the cost.'),
  ('decision', 'advanced', 'final', null, 25, 'The likelihood 0.850000 is used as a posterior twice: by hand in the EKPAN lottery''s Bayes step, and in the Analyzer as the Success chance given Bright spot, with the Dry hole chance given Bright spot typed so the pair still sums to 100. What goes wrong in each?', '["Both value the drill after a bright spot at 298.2500, because the Analyzer and the Bayes step put the same success chance against the same payoffs.", "Nothing goes wrong in either, because a likelihood equals its posterior whenever every column of the survey sums to 1.", "By hand the drill after a bright spot is valued at 298.2500 instead of 207.7989; in the Analyzer the implied Success misses 0.350000 by far more than 0.005, so the value is withheld.", "By hand nothing moves, because Bayes renormalises, and the Analyzer refuses the box as a likelihood typed where a posterior belongs."]'::jsonb, 2, '0.850000 is the chance of a bright spot given success, and the posterior is 0.646739. Typed at 46.000000 percent, a Success chance that high after Bright spot averages back far above the stated chance, and the Analyzer never repairs it.'),
  ('decision', 'advanced', 'final', null, 26, 'The EKPAN lottery''s posterior after a bright spot is typed as 65 percent, and in three trials the posterior after none is typed as 10, 9 and 8 percent. Two trials print the same gross voi of 20.51 and the third is withheld. Why?', '["After No bright spot the Analyzer''s best action is Do Not, worth 0 at either chance, so 10 and 9 never reach the value; 8 still drags the implied Success to 0.342200, past the allowance.", "The Analyzer rounds each posterior to the nearest ten percent before valuing it, so 10 and 9 merge, while 8 rounds down to zero and breaks the sum.", "The accepted trials match because both are exactly consistent, and 8 is withheld because the Analyzer refuses any posterior below 10 percent.", "After No bright spot the best action is the farm-out, which is worth the same at any success chance, and 8 is withheld because the farm-out is then refused by the Analyzer''s range check on each entry."]'::jsonb, 0, 'Drill loses money after No bright spot at 10 or 9 percent, so the posterior multiplies a branch worth nothing. The check still reads it: at 8 percent the delta is -7.800000e-3.'),
  ('decision', 'advanced', 'final', null, 27, 'The EKPAN lottery typed with posteriors of 64.7 and 9.7 percent gives an implied Success of exactly 0.350000, a delta of 0.000000e+0, and a gross voi of 19.89. At full precision the delta is 5.551115e-17 and the gross voi 19.84. Which entry describes the survey?', '["The rounded one, because a delta of exactly zero is a stronger consistency result than the binary residue of 5.551115e-17 that the full-precision entry leaves behind.", "The full-precision one: a zero delta says only that the entries agree with the stated chance, and the rounded posteriors describe a slightly different survey.", "Both equally, because the Analyzer treats every entry whose delta is inside 0.005 as the same survey, and the gap between 19.89 and 19.84 is only rounding noise on the card.", "Neither, because a delta below 1e-12 falls inside the representation allowance and the Analyzer withholds what it cannot tell from zero."]'::jsonb, 1, 'Six rounded EKPAN lottery rows pass the check with gross values from 18.41 to 20.51. The survey is the same in every row; a pass certifies agreement, not precision.'),
  ('decision', 'advanced', 'final', null, 28, 'Before the repair contradictingPosterior printed a gross voi of 75.00 beside an EVPI of 63.00. A colleague proposes restoring such values but capping each one at its EVPI. What is wrong with that?', '["Nothing, since the excess of 12 over EVPI is exactly the part the contradiction added, and removing it leaves the honest value of the survey.", "A cap sets the value too low, because EVPI binds only information derived by Bayes, and typed posteriors can legitimately be worth more than knowing the outcome in advance when the survey is a good one.", "The cap should be EMV without information, 15.00, since no survey can be worth more than the prospect it studies.", "A capped 63.00 still rests on posteriors implying 0.420000 against a stated 0.300000, and a cap never touches contradictions that print under the ceiling, such as 40.62 for the EKPAN lottery."]'::jsonb, 3, 'The with side weights a prospect succeeding 0.420000 of the time against one stated at 0.300000, so the uplift is belief, not information. The repaired Analyzer never clips and never repairs.'),
  ('decision', 'advanced', 'final', null, 29, 'The published three-outcome, four-action lottery records Farm out as the best action for Dry under perfect information. If Relinquish were listed before Farm out, what would change?', '["Nothing, because the engine prefers the action with positive payoffs in the other outcomes whenever two actions tie in one outcome.", "evWithPerfect would fall, since Relinquish pays nothing in Large or Medium and perfect information averages each action over all three outcomes.", "emvPrior would switch to Relinquish at 0.0000, because listing order decides the prior choice whenever two actions tie in any outcome.", "The action recorded for Dry would read Relinquish, and evWithPerfect 133.0000 and the EVPI of 24.0000 would stay where they are."]'::jsonb, 3, 'Farm out and Relinquish both pay 0.0000 in Dry at no cost; the strictly greater comparison keeps the first listed. EVPI takes the best value per outcome, which is 0.0000 either way.'),
  ('decision', 'advanced', 'final', null, 30, 'A write-up must report the value of the published threeByThree survey on the three-outcome, four-action lottery. Which report survives review?', '["Worth 1.2000 gross and -10.8000 net at a cost of 12.0000, against a ceiling of 24.0000, all of it from the Dim reading, with the four actions valued in the engine''s lottery form.", "Worth buying, since Drill alone after a Bright reading is worth 227.1875, far above both the 109.0000 it is worth at the prior and the survey''s cost of 12.0000, so the best reading carries the case.", "Worth 110.2000 with information against 109.0000 without, which after the survey cost of 12.0000 leaves the acquisition branch of the information tree a net gain of 98.2000 to report.", "Worth 1.2000 net of its cost against a ceiling of 24.0000, a figure the VOI Analyzer would reproduce exactly once the three-outcome lottery and its three readings are typed into its form."]'::jsonb, 0, 'Bright and Flat lead to Drill alone, the action the prior already chose, so only Dim''s switch to Farm out adds value. The Analyzer offers two actions and would lose Drill with partner and Farm out on the way in.'),
  ('decision', 'advanced', 'final', null, 31, 'On a two-branch chance node paying 10 and 30, one probability is typed as the text "0.5" beside 0.5; on a second copy the probability on the branch paying 10 is left empty beside 1 on the branch paying 30. What does each node roll back to?', '["20.0000 and a refusal, since an empty probability leaves the sum short of 1 and the engine returns a message that names the node at fault instead of a value.", "A refusal and 30.0000, because a probability typed as text is not a number and is refused in the same way as a payoff typed as \"20abc\", before any weighting.", "20.0000 and 30.0000: text that reads as a number is converted, and an empty probability is read as 0, so the second node weights only the branch paying 30.", "20.0000 both times, because an empty probability is shared out evenly with the other branch before the sum is checked."]'::jsonb, 2, 'A cleared probability usually surfaces as a sum that is not 1; it passes only when the other branches already sum to 1, and then its branch vanishes from the weighting without a message.'),
  ('decision', 'advanced', 'final', null, 32, 'A reviewer checks, on the decision where A pays 20 meant at a cost of 5 and B pays 12, that A''s branch value equals its payoff less the intended cost. What does A reading 20.0000, and on another copy 25.0000, reveal?', '["At 20.0000 the payoff was typed as the text \"20\", and at 25.0000 a probability was typed as text, each converted with a rounding error.", "At 20.0000 the cost was never charged, being text, empty or absent; at 25.0000 a cost of -5 was accepted as money received.", "Both are refusals the reviewer missed, since the engine returns the payoff unchanged whenever it rejects a cost.", "At 20.0000 the cost was charged after the branch was chosen, and at 25.0000 it was charged twice in the wrong direction."]'::jsonb, 1, '"5" as text converts to 5 and gives 15.0000; anything else non-numeric is 0, and a negative cost is a receipt. A stays the first move in both, so only the arithmetic shows it.'),
  ('decision', 'advanced', 'final', null, 33, 'At p = 80 / 350 on the EKPAN lottery the engine names Farm out; at success 0.200000 the published drillFarmOut tree names Drill. Which of these results is the tie rule at work?', '["Only drillFarmOut, an exact tie at 12.0000 with Drill listed first; at 80 / 350 the two values differ by -7.11e-15 and the choice is that binary residue.", "Both, since each is an exact tie and the engine names the branch it was given first, which is Drill on the published tree and Farm out on the EKPAN lottery.", "Only the lottery, because at 0.228571 the EVPI peaks at 61.7143, and the engine breaks a tie there toward Farm out, the one action on the lottery that cannot lose money.", "Neither, because the engine has no tie rule at all, and each of the two results comes from floating-point residue in the last binary digits of the two values."]'::jsonb, 0, 'The first listed option wins an exact tie because the comparison is strictly greater. On the lottery Drill is listed before Farm out, so Farm out winning at 21.7143 against 21.7143 can only be residue.'),
  ('decision', 'advanced', 'final', null, 34, 'The Analyzer tie case (Success 25 percent paying 200, Dry hole 75 percent paying -50, decision cost 12.5, survey cost 5.0000) names ''Drill Exploration Well'' as optimal and gives a gross voi of 25.00. What do those two outputs tell a reader?', '["Drilling is better by a margin of 25.00, the value the survey adds on top of the drill''s EMV without information of 0.00.", "The survey is worth 25.00 because the Analyzer drops the tied Do Not action and values the information against the drill alone.", "The recommendation is only the listing order, since acting and Do Not are both worth 0, and the survey is valuable because a decision that unsettled can be tipped by any signal.", "The inputs are inconsistent, because a tied prior leaves the implied chances undefined, so 25.00 is a figure from before the repair."]'::jsonb, 2, 'Acting is 0.25 x 200 plus 0.75 x -50, less 12.5, which is 0. EVPI peaks at a switch for the same reason, 61.7143 at 0.228571 on the EKPAN lottery.'),
  ('decision', 'advanced', 'final', null, 35, 'The EKPAN information tree is saved with a survey cost of 24.8250 and briefed in Decision Studio. What do its decision rows say?', '["Optimal EMV 75.7500 on \"No further information\", because at a cost equal to the gross value the engine declines to spend money on an indifferent survey.", "Optimal EMV 100.5750 on \"Acquire CSEM survey\" and an advantage of 24.8250, since the brief reports the information before its cost.", "Optimal EMV 92.5750 and an advantage of 16.8250, the rows this tree prints whatever survey cost is saved with it.", "Optimal EMV 75.7500 on \"Acquire CSEM survey\", a next best of 75.7500 and an advantage of 0.0000: the survey sits at its gross value and the move named is the branch listed first."]'::jsonb, 3, 'Acquiring is 100.5750 less 24.8250, which is 75.7500, tying no further information. On an information tree the advantage row is netEvii, 0.0000 here, and the tie goes to the first branch.'),
  ('decision', 'advanced', 'final', null, 36, 'The published dominantAction and certainOutcome lotteries both return an EVPI of 0.0000. What makes perfect information worthless in each?', '["Both have equally likely outcomes, so perfect information splits evenly and adds back to emvPrior, 65.0000 in one and 260.0000 in the other.", "On dominantAction, Always is best in both outcomes, so knowing the outcome changes nothing; on certainOutcome, Sure has probability 1.000000, so there is nothing to learn.", "Both are refused before valuation and report 0.0000 in place of a message, since one outcome in each carries no payoff.", "On dominantAction the two actions tie, and on certainOutcome the Never outcome pays nothing, so each 0.0000 is residue."]'::jsonb, 1, 'Always pays 100.0000 / 50.0000 against Never''s 10.0000 / 5.0000, so emvPrior and evWithPerfect are both 65.0000; certainOutcome reads 260.0000 on both.'),
  ('decision', 'advanced', 'final', null, 37, 'An analyst sweeps the success chance on the EKPAN tree''s drill outcome node away from 0.350000, rebalancing its other branches, while the farm-out node keeps its typed 0.350000. What does the tree now describe?', '["Two different prospects, since chance nodes are independent unless drawn otherwise, and the two nodes shared 0.350000, 0.150000 and 0.500000 only because they were typed alike.", "The same prospect under a sensitivity, because the engine links chance nodes with matching outcome names and moves the farm-out with the drill.", "Nothing at all, since two chance nodes with the same outcome names must carry the same probabilities or the rollback returns a message.", "A correlated model in which the farm-out now depends on the drill result, priced by the rollback through a later decision node."]'::jsonb, 0, 'Neither module models correlation beyond what the tree is drawn with. A clean rollback of 105.0000 says nothing about whether the two nodes still describe one rock.'),
  ('decision', 'advanced', 'final', null, 38, 'Which sentence reports the EKPAN lottery''s CSEM survey value completely?', '["Worth 19.84 gross and 11.84 net at a cost of 8.0000 against an EVPI card of 52.00, the survey''s full value on the lottery.", "Worth 16.8250 at a cost of 8.0000, below a ceiling of 52.0000, which is also the price at which buying it becomes neutral.", "Worth 24.8250 net of its 8.0000 cost against a ceiling of 61.7143, the EVPI at the drill against farm-out switch.", "Worth 24.8250 gross and 16.8250 net at a cost of 8.0000, against a ceiling of 52.0000, with Drill, Farm out and Walk away available; the two-action Analyzer gives 19.84."]'::jsonb, 3, 'A value of information needs its actions, its tree and its consistency: 19.84 is right for two actions, and the neutral price is the gross 24.8250, not the net.'),
  ('decision', 'advanced', 'final', null, 39, 'Four entries reach the rollback: a payoff summary carrying NPV P90 185, NPV P50 390 and NPV P10 710 but no mean; a payoff typed "20abc"; a payoff left empty; and a cost typed "abc". Which does the engine refuse?', '["All four, since each is an entry the engine cannot read as a number, and it refuses a tree rather than guess a value for it.", "The summary and \"20abc\"; the empty payoff is read as 0 and the \"abc\" cost is charged as 0, both without a message.", "Only \"20abc\", because a summary without a mean is valued at its NPV P50 of 390, and empty or text entries count as 0.", "The summary, the empty payoff and \"20abc\", while the cost typed \"abc\" passes alone, because a cost is optional and a payoff is not."]'::jsonb, 1, 'The two refusals read "Distribution payoff has no finite mean" and "Terminal payoff is not a number". An empty payoff silently turns a branch paying 20 at a cost of 5 into -5.0000, and an unreadable cost lifts it to 20.0000.'),
  ('decision', 'advanced', 'final', null, 40, 'The published three-outcome, four-action lottery is drawn in the Decision Tree Builder as a root decision with one costed branch per action, and briefed twice: with all four actions, and after Drill with partner is pruned as never best. What changes on the brief?', '["Nothing, because an action that is never best at any probability cannot enter any row the brief prints, just as pruning it leaves emvPrior 109.0000 and the EVPI of 24.0000 unchanged.", "Optimal EMV falls to 54.5000, because pruning the partner removes the half-scale copy the rollback leaned on to reach 109.0000.", "Optimal EMV stays 109.0000 on Drill alone, but the Next best alternative falls from 54.5000 to 31.0000 and the Decision advantage rises from 54.5000 to 78.0000.", "Only the Decision advantage, which the brief measures against whichever branch is listed second, while the Next best alternative row keeps its 54.5000 from the earlier save of the tree."]'::jsonb, 2, 'Next best is the largest other root branch value, and with the partner gone that is Farm out at 31.0000. No engine value moves, yet the brief''s margin had been measured against an action that could never win.'),
  ('decision', 'advanced', 'final', null, 41, 'IRRI''s two readings both put success at 20 percent, and the published uselessSignal case''s two readings both leave the posterior at 0.300000. Each signal says the same thing whatever it reads. Why is one worth 0.0000 and the other withheld?', '["uselessSignal''s posteriors average back to the stated 0.300000, so ignoring it earns emvPrior and it is worth 0.0000; IRRI''s average to 0.200000, a prospect nobody stated.", "Both are worth 0.0000 in truth, and IRRI is withheld only because the Analyzer cannot display a zero value of information without raising a consistency warning beside it.", "uselessSignal is derived from likelihoods and so exempt from every check, while IRRI is withheld because the Analyzer will not value two indicators typed with identical percents of outcome chances.", "IRRI is worth -15.00 because its readings point toward a poorer prospect, and the repaired Analyzer withholds values that would discourage buying."]'::jsonb, 0, 'Averaging Bayes posteriors over the readings returns the prior, which sets the floor of 0; uselessSignal''s actions both read 43.0000. IRRI''s readings return 20 percent, so the -15.00 it printed before the repair was never a value.'),
  ('decision', 'advanced', 'final', null, 42, 'A survey''s likelihoods given Success are typed as 0.333333 for each of three readings, and every other column is sound. What does the Bayes engine return?', '["A value, since the EC4-0 repair gave each likelihood column the same 1e-12 representation allowance that it gave the implied-prior half percent check.", "A value, because likelihoods are checked across each reading''s row rather than down each outcome''s column, and three readings of 0.333333 do not form a row.", "A refusal naming the Success column at 0.999999, because each likelihood column faces the same 1e-6 test as a chance node, with no binary allowance.", "A refusal naming the readings, because three readings with equal likelihoods carry no information and the engine will not value a signal that cannot change anything."]'::jsonb, 2, 'Three copies of 0.333333 sum in binary to a gap of just over 1e-6, and the tolerance has no allowance for that (EC4-8 is open). Typing seven places, 0.3333333, would pass.');
